export type ManualArticle={id:string;title:string;area:string;availability:'Pilot workflow'|'Release preview'|'Development preview';steps:string[];notes:string[];keywords:string[]};
export const manualRevision='2026-09-28-r4';
export const operatingManual:ManualArticle[]=[
{id:'property-first-setup',title:'Set up a property before accepting bookings',area:'Getting started',availability:'Pilot workflow',steps:['Choose the property from the property selector at the top of the PMS. Check its name and business date before changing anything.','Open Property settings. Confirm the property name, time zone and operating model, then save the property details. Use Hotel for individually bookable rooms or Whole-home vacation rental for an entire home sold as one unit.','Open Inventory and confirm each room type and physical room. Add the approved room numbers, map each room to its correct room type and verify the property total against the owner-approved room list. Do not use sample numbers as real hotel room labels.','Open Rates & plans. Confirm an active rate plan for each room type, set the nightly prices and dates, then configure the property’s City, State, Lodging, Resort and Technology charges as applicable. Review the guest total before saving.','Open Inventory and configure room-type capacity for the dates you plan to sell. Compare configured capacity with physical rooms and dated maintenance closures. Resolve every missing-capacity date before quoting or accepting a stay.','Open Connections and review each provider’s exact status. Complete the provider’s test and mapping steps before treating payments, messaging or OTA distribution as connected. A saved setting or draft is not proof of a live connection.','Create a controlled test reservation with approved test data. Check the stay value, taxes and fees, room assignment, folio, check-in, checkout and resulting housekeeping task. Reopen the stay and reports to verify the saved result.','Before staff begin live shifts, review Staff access, complete owner and manager training, and follow the release-status page for database, backup, payment and provider acceptance gates.'],notes:['This checklist links existing setup workflows; it does not provision accounts, apply hosted database changes, certify integrations or approve a property for live operation.','Use a test property and test guest details for rehearsal. Do not create fake reservations or room records in an operating hotel to make capacity appear available.','For the Red Roof Inn Ridgeland test workspace, 67 room records were added for testing; their labels still need confirmation against the approved physical room map before they represent actual hotel inventory.'],keywords:['setup','property setup','new hotel','first use','getting started','rooms','room types','capacity','taxes','rates','launch checklist']},
{"id": "historical-performance", "title": "Review historical occupancy, ADR and RevPAR", "area": "Reports", "availability": "Release preview", "steps": ["As an owner or manager, open Reports and choose Historical overnight performance.", "Choose From and Until (exclusive), then select Load historical performance. Review closed days, unclosed days and dates without complete inventory before interpreting rates.", "Review period occupancy, original overnight ADR and original overnight RevPAR, then inspect the daily table for each service date. Use Export historical CSV or the copyable CSV to save the results."], "notes": ["Occupancy is occupied room-nights divided by effective unit-nights reviewed at service-day close. ADR is original overnight accommodation divided by occupied room-nights. RevPAR is original overnight accommodation divided by effective unit-nights.", "Same-day charges, taxes, property fees and posted corrections are not included in ADR or RevPAR. Period rates use total amounts and room-nights; they are not averages of daily percentages or rates. Net accommodation after posted corrections includes overnight, same-day and other accommodation plus signed corrections; taxes and property fees are excluded.", "An unclosed date suppresses whole-period rates. Missing or zero capacity makes capacity-based occupancy and RevPAR unavailable; unavailable is not zero. Capacity reflects the configuration saved at close, not reconstructed historical physical inventory.", "This reporting workflow is a release preview until the connected property service and saved close data are verified for your property."], "keywords": ["historical performance", "occupancy", "ADR", "RevPAR", "daily statistics", "reports"]},
{"id":"daily-ops-brief","title":"View and download the daily operations brief","area":"Reports","availability":"Pilot workflow","steps":["Open Today and verify the selected property, business date and time zone before reviewing the shift.","Review Ready rooms, In house, Arrivals today, Departures today and Rooms to prepare. The brief also lists current manager-attention items when available.","Select Download daily brief CSV to save the current aggregate summary. Reopen or refresh the workspace before handing off a shift if another staff member may have changed rooms or reservations.","For closed-day occupancy, ADR and RevPAR, use Reports and the Historical overnight performance report instead."],"notes":["The CSV includes the property name, business date, time zone and room/stay counts; it excludes guest names, room labels, reservation references, folios, payment records and identity data.","The daily brief is a current workspace snapshot. It is not a historical revenue report, night audit, payment settlement or demand forecast.","Scheduled email delivery is managed separately and must be activated and tested before you rely on it."],"keywords":["daily brief","daily summary","manager summary","download CSV","today","shift handoff","occupancy"]},
{"id":"scheduled-manager-brief","title":"Configure a scheduled manager summary","area":"Reports","availability":"Release preview","steps":["As an owner or manager, open Today for the property that should send the summary.","In Scheduled manager summary, enter the authorized recipient email address and choose a send time in the property's displayed time zone.","Select Enable scheduled summary email. Confirm that you are authorized to send this property's operational summary to that address, then select Save schedule.","Use Refresh status and review Recent delivery status. Sent confirms provider acceptance, not that the recipient read the message. Retry pending, Review required, or Dead needs administrator review."],"notes":["This is a release preview until the database migration, scheduled worker flag, Resend sender configuration, and hosted delivery check are complete. Saving an opt-in setting alone does not activate delivery.","The scheduled message contains property name, business date, time zone, and aggregate room/stay counts only. Guest names, room numbers, reservation references, payments, folios, and identity details are excluded.","Disable the schedule or change the recipient to cancel queued or retrying messages for the old address. A message already claimed by the worker may still finish sending. Do not put API keys or passwords in the PMS page or email field.","No email is sent by the local preview. Do not rely on it for shift handoff until delivery is verified in the property workspace."],"keywords":["scheduled manager summary","daily email","consent","send time","recipient","delivery status","retry"]},
{"id": "reservation-migration-import", "title": "Import future reservations from another PMS", "area": "Migration", "availability": "Release preview", "steps": ["In the destination property, create and verify its room types and nightly inventory before importing. Open Switch to iRatePilot and download the CSV template.", "Enter a stable Source PMS code and preserve each source reservation ID. The template accepts guest name, room type, arrival, departure, guest count, USD accommodation and tax amounts.", "Save the CSV as UTF-8. Use YYYY-MM-DD dates, a departure after arrival, and room-type names that match the destination property exactly. Keep the file to 1 MB or less, no more than 500 rows, and each stay to 1–30 nights.", "Choose the file and select Validate and preview. Review every guest, source reference, room type, date and charge. Resolve errors in the source export and upload the corrected file before committing.", "Check I reviewed the source IDs, room mapping, stay dates, and charges, then select Commit reservations once. Confirm the saved receipt and refresh Reservations to verify the imported stays.", "Assign destination room numbers separately using Assign a room before arrival. Verify deposits and payments from the source PMS separately; this reservation import does not record or collect them."], "notes": ["This import currently covers future reservation records only. It does not import room types, physical rooms, rate plans, guest profiles beyond the guest name, identity documents, users, historical stays, deposits or payments.", "Only USD is accepted. Accommodation and tax totals are imported as stay values; tax categories, resort or technology fee breakdowns, and nightly charge allocation are not migrated by this file.", "Use only approved guest data. Never place card details, passport numbers, identity images or other sensitive documents in this CSV.", "A commit rechecks availability before writing the batch. If validation reports that inventory changed, review the updated errors and retry only after correcting the conflicts.", "The workflow depends on the connected hotel service. The database procedures are not part of this repository’s migration set, so this guide is a release preview until the exact service-side procedures are verified and covered by reproducible tests."], "keywords": ["migration", "import", "PMS switch", "CSV", "future reservation", "source ID", "cutover"]},
{id:'reservation-timeline',title:'Find a future stay on the reservation timeline',area:'Front desk',availability:'Pilot workflow',steps:[
 'Open Reservations for the correct property and find Reservation timeline.',
 'Choose Start date to jump directly to an arrival date. The table shows that date and the following six nights. You can also use Next week, Previous week or Current week.',
 'Find the room number in the first column. Bookings without a room number appear in the Unassigned row. On a tablet or phone, scroll the table sideways to see all seven dates.',
 'Select the guest name on a stay night to open that reservation. For a confirmed future booking, use Assign room before arrival to save a room number.',
 'Refresh workspace to load changes made by other staff. After assigning a room, verify the reservation is displayed against the intended room.'
],notes:[
 'Start date is available on the live pilot. The timeline displays the workspace snapshot, not a continuously synchronized feed.',
 'Departure dates are excluded. A stay departing on the 23rd occupies the night of the 22nd, not the night of the 23rd.',
 'Maintenance marks scheduled room closures. Housekeeping status beside the room is its current status, not a prediction for the selected date.',
 'An empty cell is not a price quote or a guarantee of sellable inventory. Booking still checks room type, capacity, rates and restrictions.',
 'An overdue in-house stay remains displayed as a room hold. Resolve it through the stay workflow; do not assume its original departure frees the room.'
],keywords:['timeline','calendar','future','start date','unassigned','room rack']},
{"id": "quick-room-status", "title": "Change room status from Today", "area": "Housekeeping", "availability": "Pilot workflow", "steps": ["On Today, click a room number to open its actions.", "As an owner or manager, select Clean after confirming the room is cleaned, or Dirty if preparation is required.", "For multiple rooms, click one room number and Shift-click another to select the range. Use checkboxes or Ctrl/Cmd-click for separate rooms.", "Select Clean selected rooms or Dirty selected rooms. Review the result shown for each room; some rooms may be skipped or fail.", "For a room labeled Maintenance, select Review maintenance. In the maintenance panel, find the active closure for that room and select Review release. Enter a reason and confirm that you reviewed the room’s readiness before releasing it.", "Releasing the closure restores its dated availability but keeps the housekeeping status unchanged. Finish any needed repair and cleaning, then return to Today and select Clean. If the room still needs preparation, select Dirty and complete its turnover work first."], "notes": ["Clean skips occupied rooms and rooms with active maintenance closures. Dirty does not release maintenance.", "Direct Clean is an owner/manager readiness confirmation; it does not invent staff cleaning or inspection records.", "Ready rooms counts clean, vacant rooms with no active closure or unfinished turnover task."], "keywords": ["clean", "dirty", "maintenance", "release maintenance", "shift", "multiple", "bulk", "ready"]},
{"id": "front-desk-shortcuts", "title": "Use the Today front-desk shortcuts", "area": "Front desk", "availability": "Pilot workflow", "steps": ["Open Today after selecting the property you are working in.", "Choose Check In to jump to today's arrivals. If no guest is due to arrive today, it takes you to the room board; choose an available room number there to start a walk-in check-in.", "Choose Reservations to find and manage stays, Housekeeping to review room readiness and assignments, Payments to open folio/payment reports, Guest Search to find saved guest profiles, or Reports for property statistics.", "Verify the selected property before making changes. Use the browser Back button only for page navigation; switch PMS areas with the left menu or these shortcuts."], "notes": ["The shortcuts open existing PMS areas and do not bypass role permissions or confirmation steps.", "Payments opens folio and payment reports. To collect or record a payment, open the correct reservation and use its stay/folio workflow."], "keywords": ["today", "home", "shortcut", "check in", "housekeeping", "payments", "guest search", "reports"]},
{"id":"shared-tablet-kiosk","title":"Run shared-tablet guest arrival registration","area":"Guest experience","availability":"Release preview","steps":["On the reservation, open Phone pre-check-in and create or refresh the guest’s private arrival link. For a shared tablet, choose Copy shared-tablet kiosk link and send it only to that guest or open it on the assigned tablet.","The kiosk link is tied to one reservation and expires after 24 hours. If it went to the wrong person, select Disable link or Replace link before issuing another one.","On the tablet, the guest reviews the property and enters their full name, phone and estimated arrival time. They may scan or upload an ID image for on-device name/address suggestions, then must review every suggestion; the PMS does not save the image, document number or birth date.","The guest confirms the details and selects Submit arrival details. Wait for the saved confirmation, then select Finish and clear shared tablet. The page removes the token from the address bar and returns to a blank Welcome screen.","Staff opens the reservation and reviews the submitted details. Verify the guest against the original ID and reservation, handle payment and room readiness, and complete check-in through the normal staff workflow."],"notes":["This is a release preview until it is deployed and verified on the live site and a physical tablet.","The kiosk has no public reservation search. Keep each link private; anyone holding its token can submit arrival details for that one reservation until the link expires or is disabled.","The kiosk does not collect a payment, assign a room, provide a digital key or complete hotel check-in. It is guest registration only.","If the kiosk is idle for two minutes before submission, it clears the guest form and returns to Welcome. After successful submission, contact fields are cleared and the confirmation shows no guest details. Staff can disable the token from the reservation."],"keywords":["kiosk","shared tablet","tablet check in","guest arrival","pre-check-in","token","clear tablet","ID scan"]},
{"id": "advance-room-assignment", "title": "Assign a room before arrival", "area": "Front desk", "availability": "Pilot workflow", "steps": ["Open Reservations for the correct property. Find a confirmed booking and select Prepare arrival for a future stay, or Check in / prepare for an arrival today.", "In Assign room before arrival, choose a Room number, then select Assign room. The stay remains Confirmed.", "Check the saved room number in the reservation list. Reopen the same booking to change it to another available room of the booked type.", "If a save times out, use Retry saved assignment, then Assign room to recover the original request. Check the refreshed reservation list afterward."], "notes": ["Assignment does not collect payment, check in the guest or mark the room clean. Confirm readiness on arrival.", "Rooms with overlapping assigned stays or maintenance during the booked nights are excluded. Departure dates are excluded, so back-to-back stays can share a room.", "This action supports arrivals today or in the future. Use the room-move workflow for guests already in house."], "keywords": ["assign", "advance", "future", "room number", "preassign", "reservation"]},
{"id": "guest-invoice", "title": "Issue a guest invoice using saved details", "area": "Finance", "availability": "Pilot workflow", "steps": ["As owner or manager, select the correct property and stay in Reservations. Open Manage stay or Check in / prepare, then View reservation folio and Preview billable charges.", "Review Recorded, Already invoiced after credits, Transferred to billing accounts and Available amounts. Only the available balance can be included in the guest invoice.", "Under Bill to, choose Same as guest for the saved guest contact/address or Use saved billing details for a separate recipient. Review and edit the copied fields. Enter issuer legal details separately and check the due date.", "Select Review invoice. Check the issuer, recipient, amounts and due date. Use Edit review to correct details, then Confirm and issue invoice.", "After confirmation, select Load issued invoices, open the invoice and use Print invoice / Save as PDF if needed. If interrupted, use Check invoice result before preparing another invoice."], "notes": ["Copying recipient details changes this form only. It does not change the guest record or an issued invoice, and does not copy identity-document numbers or birth dates.", "If you edit while a copy is loading, newer edits are preserved. Follow the message and repeat the copy action only if needed.", "A full transfer to a company leaves nothing available for a guest invoice. Review the routing rather than adding transferred charges back. Company-account features may still be release previews.", "Issuing an invoice does not collect payment. A credit note does not automatically refund money or adjust the guest folio. Staff should ask an owner or manager to issue or correct invoices."], "keywords": ["invoice", "same as guest", "bill to", "recipient", "issuer", "print", "recovery", "transferred"]},
{"id": "finance-amounts", "title": "Understand booking value, revenue and payment", "area": "Finance", "availability": "Pilot workflow", "steps": ["Use the reservation price to review booked value. It describes the agreed stay charges; it is not proof of payment or completed nightly revenue.", "Use Service-day close and its preserved reports for service-date allocations. Resolve blocked arrivals and allocation issues before closing. Blocked rows are excluded from partial totals.", "Review actual receipts and the current folio balance separately. A manually recorded external payment documents money already received; it does not charge a card.", "Have the authorized accounting operator reconcile ledger postings and provider or bank settlement separately. A cashier drawer close does not close the service day."], "notes": ["Example only: a two-night $246 stay can allocate $125.50 then $120.50, with a $5 per-stay technology fee appearing once. Use the actual accepted booking and property settings.", "Closing a service day does not collect money or add another guest charge. An unfinished service day cannot close in the property time zone.", "Stripe TEST confirmations are sandbox results; they do not settle the guest folio or collect real funds.", "Tax allocation is not proof of a tax return or remittance. These operating instructions are not a declaration that all production accounting and payment integrations are activated."], "keywords": ["booked value", "night audit", "revenue", "payment", "tax", "fee", "reconciliation", "cashier"]},
{id:'pickup-schedule',title:'Configure and review scheduled revenue captures',area:'Reports',availability:'Release preview',steps:[
 'As the property owner, select the intended property. In Reports, choose Booking pickup · preview and find Revenue capture schedule.',
 'Select Load schedule status. If the service is unavailable, stop and ask your administrator about activation; an error does not mean there is no schedule.',
 'Review Capture health and its server check time. Overdue means the latest eligible occurrence has no completion after its window. An older successful capture does not clear this warning. Reload to check again; this is not continuous monitoring or a complete history audit.',
 'Set Daily capture time in the property time zone, Stay nights to capture from 1 to 31, and Allowed delay from 0 to 3600 seconds. The delay is the permitted capture window after the scheduled time, not a guarantee of exact timing.',
 'Select or clear Enable saved schedule, then select Save capture schedule once. Select Load schedule status again to confirm the saved values before making another change.',
 'If saving times out or cannot be confirmed, reload the status before editing again. Another owner may have changed the settings; review the current values instead of repeating an outdated edit.',
 'Review Recent scheduled capture results. Captured means a snapshot was saved. Missed means the scheduled opportunity passed without a capture. Failed attempt means that attempt failed; a later successful retry may appear separately. Check the scheduled day and schedule version when comparing entries.'
],notes:[
 'Development only: these controls and services are not activated on the live PMS. Enabling saved settings does not install or confirm an automatic background job. Hosted scheduling and monitoring still require verification.',
 'Only owners can change or read schedule settings through this workflow. Each saved change creates a new version and an audit record.',
 'Captures retain their actual observation time. Missed days are recorded without inventing historical snapshots. A capture made within the allowed delay may still be unsuitable for a pace comparison that requires matching capture times.',
 'The capture must finish on its scheduled property-local day. A delay window that crosses midnight does not permit reconstructing the previous day; a missing completion becomes overdue after midnight.',
 'A failed capture attempt waits at least one minute before another attempt is eligible. Eligibility does not guarantee a retry: the background service must run while the capture window remains open.',
 'At a daylight-saving change, a nonexistent local capture time is missed. A repeated local time uses the later occurrence. Review the schedule after changing the property time zone.',
 'The screen shows up to 31 recent runs and 31 recent failed attempts. It is not a complete monitoring or alerting service. A missing entry alone does not prove a scheduled job ran.'
],keywords:['schedule','scheduled capture','pickup','missed','retry','capture time']},
{id:'booking-pickup',title:'Save and compare booking pickup snapshots',area:'Reports',availability:'Release preview',steps:[
 'As an owner or assigned manager, select the intended property. Open Reports and choose Booking pickup · preview.',
 'To save a snapshot, choose First stay night and End date (excluded), covering 1 to 31 nights. Select Save pickup snapshot once. The server supports current and future nights, up to 365 days ahead.',
 'If the response is interrupted, use Retry saved snapshot. Keep the same browser session so the saved request remains available. Do not clear recovery storage or create replacement requests to work around an uncertain result.',
 'After Snapshot saved appears, select Load recent captures. Use Load older captures when the baseline is not in the first page. Loading older captures preserves your selection; loading recent captures resets it.',
 'Choose a Baseline capture and a Later capture, then select Compare captures. Use captures covering the same stay nights and room types. Each row compares the later saved count with the earlier one.',
 'Review room-night change, room revenue change, current occupancy, current ADR and current RevPAR. On a narrow screen, scroll the table sideways. Use Previous rows and Next rows for comparisons longer than 50 rows.',
 'For a specific night and room type, select Baseline details or Later details, then Load reservation evidence. Review saved reservation references, revisions and room charges. Use Load more reservations when offered, or Close reservation details to return to the comparison.',
 'Save another snapshot later to measure subsequent changes. Download pickup CSV includes every comparison row, even when only one page is visible.',
 'To compare booking pace, load two captures covering different stay dates. After Compare captures, use Booking pace below the pickup table. Select Reference stay night and Current stay night, then Compare booking pace.',
 'Choose comparable dates deliberately, such as matching weekdays or similar event periods. The reference night must be earlier. Both snapshots must have the same number of property-local days before arrival and the same capture clock second.',
 'Review booked-night, room revenue and capacity differences. Positive means the current night has more; negative means less. Check reference and current occupancy alongside capacity: occupancy can increase because fewer rooms are sellable. A change from 20% to 30% is 10 percentage points.',
 'Select Reference reservations or Current reservations to inspect the saved evidence for that room type and night. Close pace details returns you to the report. These are historical capture details, not a fresh reservation list.',
 'Use Previous pace rows and Next pace rows for reports with more than 50 room types. Download pace CSV includes all rows for the selected comparison. Printing includes all comparison rows and restores your screen page afterward.'
],notes:[
 'This is an unpublished development workflow. The capture and report services are not activated on the live database. An unavailable-service message does not mean the property has no bookings. Scheduled capture is not active.',
 'Pickup is the net change in booked room nights and accommodation revenue, including cancellations and modifications. It is not gross new bookings, earned revenue, collected payments or a demand forecast.',
 'Occupancy divides booked room nights by effective sellable capacity. ADR divides booked room revenue by booked room nights. RevPAR divides booked room revenue by effective sellable capacity. These are saved booked-value measures, not actual overnight performance.',
 'Unavailable is not zero. Revenue requires a complete, unambiguous nightly quote allocation matching the stay and room total. Unquoted or changed prices can leave revenue unknown while booked room counts remain visible. Missing or zero capacity prevents occupancy and RevPAR calculation.',
 'Snapshots do not change reservations, rates or inventory. Your current property permission is required when retrying. If recovery cannot be read, ask your PMS administrator to reconcile the request before replacing it.',
 'Reservation evidence reflects the selected capture, not the current guest record. The server checks the full snapshot totals before returning a page. Missing or inconsistent evidence is rejected; do not treat an error as an empty reservation list. Unknown room charges remain unavailable.',
 'Manual captures currently allow 20 new successful captures per property in a rolling hour. An authorized retry of the same saved request does not create another capture. This development limit is not a subscription entitlement.',
 'Select Download pickup CSV after comparing captures to download every row, including rows on other pages. The file includes capture timestamps and uses the current room type names. Occupancy is a ratio (1 means 100%); ADR and RevPAR are rounded to cents. This screen does not provide automatic rate recommendations.'
,
 'Pace compares different stay nights at matched booking lead times; pickup measures changes for the same night. Neither is a demand forecast or an automatic pricing recommendation.',
 'If timing or room types do not match, the pace row explains why it is unavailable. Missing history is never treated as zero. Manual captures may not align; scheduled capture remains unfinished. Changing either date or the property time zone clears the previous comparison and download control.',
 'Occupancy is unavailable when sellable capacity is missing or zero. Values above 100% remain visible so overselling is not hidden. Occupancy figures are rounded to one decimal place in the report and CSV.'
],keywords:['pickup','pace','snapshot','RevPAR','ADR','booked revenue','capture']},

{id:'property-demand-forecast',title:'Prepare a property demand forecast',area:'Reports',availability:'Development preview',steps:[
 'As an owner or assigned manager, open Rates & plans and save the property’s event or seasonal demand adjustments for the dates you want to review.',
 'Open Reports, choose Booking pickup · preview, load recent captures, then choose a baseline and later capture and select Compare captures.',
 'Scroll below Booking pace to Property demand forecast. Choose a future stay night and select Prepare forecast.',
 'Review projected booked rooms and occupancy, estimated ADR and accommodation, comparable history, and any saved event or seasonal adjustments shown.',
 'Select Save forecast for accuracy reporting to preserve an immutable manager-review record. If the save response is interrupted, retry the same save; the browser reuses its original request.',
 'After a service date is closed, open Forecast vs actual under Booking pickup and select Load accuracy report. Review how many saved forecasts have a complete, capacity-matched result and the room, occupancy, ADR and accommodation errors.'
],notes:[
 'The forecast is a deterministic estimate for the whole property. It requires at least three earlier closed nights with the same weekday and booking lead time, complete pickup captures, and historical capacity that matches the current room inventory.',
 'If the forecast is unavailable, load older pickup captures or choose another future night. Missing or inconsistent history is never treated as zero.',
 'The forecast does not change rates, availability or reservations. Event and seasonal factors are manager-entered inputs; the comparison report uses only closed nights with complete inventory and unchanged capacity. Incomplete or changed-capacity nights remain visible with an explanation and are excluded from accuracy averages.',
 'The archive and comparison are release preview until the required database migration is installed and hosted authorization, history, and hotel acceptance are verified.'
],keywords:['demand forecast','forecast','event','seasonality','booking pace','occupancy','ADR']},

{id:'account-security',title:'Check your account security',area:'Staff access',availability:'Release preview',steps:[
 'In the private preview, sign in with your authorized owner account. Open Account security near your email in the sidebar.',
 'Select Refresh verification methods. Confirmed means the provider reports that the method was verified; Setup unfinished is not a confirmed authenticator.',
 'If the session changes or loading fails, return to sign in or refresh as instructed. Do not interpret an unavailable list as having no methods.'
],notes:[
 'The verification-method list is read-only. Adding, replacing and removing authenticators are not enabled in this preview. These instructions do not indicate that the feature is published on the live PMS.',
 'Verification methods belong to your account across properties. A confirmed method does not grant access to another property.'
],keywords:['account security','MFA','two step','authenticator','verification methods']},
{id:'other-sessions',title:'Sign out your other browser sessions',area:'Staff access',availability:'Release preview',steps:[
 'Open Account security in the private preview and wait for your account verification methods to load.',
 'In Other sessions, select I want to sign out my other sessions, then select Sign out other sessions once.',
 'Read the result. On success, other sessions can no longer renew access; this browser stays signed in.',
 'If the request times out, its result is uncertain. Read the message and confirm again before retrying. If your account changes, sign in again before taking another action.'
],notes:[
 'This affects your account across properties, not only the hotel currently selected. It does not sign out other staff accounts.',
 'Existing access in other browsers may continue until it expires. Do not treat this control as proof of immediate revocation or as a list of your devices.',
 'This control does not change your password or replace a lost authenticator. It is a release-preview feature; live activation and real multi-browser verification remain pending.'
],keywords:['sign out','other sessions','shared computer','lost tablet','session']},
{id:'authenticator-signin',title:'Use an enrolled authenticator at sign-in',area:'Staff access',availability:'Release preview',steps:[
 'Sign in with your own email and password. If the private preview requests two-step verification, open the authenticator app already connected to your account.',
 'If more than one authenticator is offered, choose the intended method. Enter its current six-digit code and submit once.',
 'If the code is rejected, use a fresh code and try again. If verification times out, follow the retry message. Continue only after the PMS confirms access.'
],notes:[
 'The prepared challenge supports authenticator apps. Phone verification and self-service recovery are not available in this preview.',
 'If you lose access to the authenticator, contact your designated PMS administrator through your established support channel. The current preview has no completed recovery workflow; do not assume that resetting a password removes the authenticator.',
 'Never send passwords, verification codes, setup keys or QR codes to support or another staff member. Use your own account on shared devices and sign out when finished.'
],keywords:['sign in','verification code','lost authenticator','recovery','two step']},
{id:'owner-invitations',title:'Invite a customer owner',area:'Platform administration',availability:'Release preview',steps:[
 'After platform administration and invitation delivery are activated, sign in with the designated platform administrator account and open /platform-admin.',
 'Under Owner invitations, enter the new owner’s email and select Prepare invitation draft. This saves a draft only. If the account already exists, resolve its confirmation or use the confirmed account for customer setup.',
 'Select Review invitation beside the saved draft. Check the recipient carefully, tick I reviewed the recipient and want to send this invitation, then select Send invitation once.',
 'Review the saved status. Provider accepted means the request was accepted by the email provider; it does not prove inbox delivery or account confirmation.',
 'The owner opens the invitation email and verifies the invitation, then enters matching passwords. Password setup does not assign a property.',
 'After the owner confirms the account, use Create customer workspace to assign the intended property. Subscription billing is a separate step.'
],notes:[
 'This workflow is unpublished and delivery is disabled until configuration and hosted acceptance are complete. Do not treat these instructions as evidence that invitations are live.',
 'Platform administrator access is distinct from being an owner of one hotel. An invitation does not make its recipient the iRatePilot platform administrator.'
],keywords:['invitation','invite owner','customer account','password','administrator']},
{id:'owner-invitation-recovery',title:'Check an interrupted owner invitation',area:'Platform administration',availability:'Release preview',steps:[
 'Select Reload invitation drafts and locate the saved email and reference. Keep that reference when reporting a problem.',
 'Draft · Email not sent means dispatch has not started. You may review and send after delivery is activated, or cancel the draft before correcting its email.',
 'Dispatch started · Awaiting result or Delivery uncertain · Do not resend requires result checking by the platform operator. Do not create a replacement invitation or assume the email was not sent.',
 'For Provider accepted · Delivery not confirmed, ask the recipient to check the intended inbox. A used or expired link requires investigation; do not assume repeated sends are safe.',
 'If a password-save result was interrupted, first try signing in with the new password. Use the existing password-reset process if needed.'
],notes:[
 'An invitation whose dispatch has started cannot be cancelled through Cancel draft. Cancelling a draft does not delete a user account.',
 'The current preview retains uncertain outcomes but does not yet provide a complete operator reconciliation tool. Escalate with the reference and avoid another send.'
],keywords:['invitation recovery','email not received','uncertain','expired link','cancel invitation']},
{id:'financial-migration',title:'Import and reconcile opening balances',area:'Migration',availability:'Release preview',steps:[
 'After financial migration is enabled for your property, open Switch to iRatePilot. Use a source export that corresponds to reservations already imported from the same PMS. Keep the original documents for comparison.',
 'In the financial upload, enter Source PMS code, Source batch reference and Cutover date. Select the Financial CSV and enter the source totals separately for receivables, prepayments and security funds. Receivables require the original debtor name and due date.',
 'Select Save financial preview once. Review Source totals reconcile and the saved source records. This stages the file; it does not post balances or collect money. Use Refresh financial batches and Open financial batch to return to a saved batch.',
 'Select Load opening accounts and periods. Choose separate receivable, prepayment, security and opening offset accounts, plus an open period containing the cutover date. Select Preview source reconciliation.',
 'For Match each entire source balance, review every source document. Choose Additional balance not already represented only for a balance that is missing. For a receivable already included in an invoice, choose Already represented by an existing invoice and select that invoice. Enter a Supporting reference for every decision.',
 'Select Review reconciliation decisions. Check I reviewed each source item and supporting reference, then Save reconciliation decisions. Saving the review still does not post balances.',
 'Review the final choices. Check I confirm the reconciled source balances for cutover, then select Post reconciled migration once. Wait for Reconciled migration posted.',
 'Open the saved batch and verify its opening and journal references or existing invoice matches. A matched invoice keeps its existing debt; it must not receive a second opening balance.'
],notes:[
 'These are release-preview instructions; activation and live acceptance are pending. Matching amounts alone do not prove that two records represent the same debt. Compare the original invoice, reservation and payment evidence.',
 'Keep prepayments and security separate from receivables. Importing a payment balance records existing money; it does not charge a card or transfer funds.',
 'This chapter covers whole-source decisions. If only part of a source balance already exists, use the separate split or combined reconciliation workflow after reviewing its allocations; do not mark the whole balance as additional.'
],keywords:['migration','import','opening balances','invoice match','receivable','prepayment','security','cutover']},
{id:'financial-migration-recovery',title:'Recover an interrupted balance import',area:'Migration',availability:'Release preview',steps:[
 'Keep the same property, account and browser session. Reopen Switch to iRatePilot. Do not start a replacement batch or clear browser storage while a result is uncertain.',
 'For an interrupted upload, select Check upload outcome. For an interrupted review save, select Check reconciliation save. For an interrupted posting, select Check reconciled posting.',
 'If the saved result is found, review it and continue from the recovered stage. A successfully saved review is not yet a posted balance.',
 'If no saved result is found, follow the offered retry or cancellation control for the original request. Confirm cancellation only when appropriate; a completed posting cannot be cancelled through a pending-request control.',
 'After posting is confirmed, review the saved batch references. If the result remains unclear, keep the request intact and contact the person responsible for migration before another financial action.'
],notes:['This release-preview workflow stores pending-request recovery in the current browser session. Switching devices or accounts does not transfer that request automatically.','A timeout does not mean the action failed. The result-check controls are designed to recover the original result without creating another balance.'],keywords:['migration','interrupted','recover','retry','duplicate','save','posting']},
{id:'daily-checklist',title:'Daily front-desk checklist',area:'Front desk',availability:'Release preview',steps:[
 'Start: select the correct property and check its date. Open Today and refresh the workspace. Review arrivals, in-house guests, departures and rooms to prepare.',
 'Cash: if you will handle cash, follow Open a cashier drawer. Count the opening cash physically; it is not a guest payment.',
 'Arrivals: open the reservation, verify guest details and choose the room. Review the guest bill and actual payment arrangement. Follow Check in a reserved guest and wait for In house before issuing room access.',
 'Walk-ins: select a room number, review the guest details, dates, room-type rate, taxes and fees, then book once. Follow the saved reservation through check-in. A quote is not a booking or a payment.',
 'Departures: open Manage stay, review the bill and payment evidence, resolve unclear balances and check out under your property procedure. Confirm the resulting turnover task.',
 'Rooms: in Rooms & housekeeping, review Room readiness and Turnover tasks. After the pending maintenance release is active, also review unfinished or urgent repairs in Maintenance. A repair completion does not make a room clean or bookable.',
 'Handover: follow Hand over your shift. Count and close your cashier drawer if required. Service-day close is a separate authorized review; do not run it solely because your shift ended.'
],notes:[
 'Use the individual guide topics for the detailed controls and confirmations. This checklist includes pending room and repair screens; check each topic’s availability before use.',
 'A delayed response does not establish whether a save succeeded. Keep the existing request and use its result-check or retry control. Do not create a replacement payment or booking just to clear an uncertain result.'
],keywords:['daily','checklist','routine','front desk','start shift','handover','quick guide']},
{id:'shift-handover',title:'Hand over your shift',area:'Front desk',availability:'Pilot workflow',steps:[
 'Refresh Today and identify remaining arrivals, expected departures, room preparation needs and guest requests for the next shift.',
 'Review any unresolved booking, payment or other save. Record the property, reservation reference, action and approximate time using your approved handover method. Preserve the original browser session and recovery controls until the result is reconciled.',
 'If you operated a cashier drawer, count it and follow Count cash and close a cashier drawer. Verify the confirmation and explain any difference between expected and counted cash.',
 'Explain remaining work to the incoming staff member. They must sign in with their own account and select the correct property. An unfinished request belonging to your session does not automatically move to their account.',
 'Once your requests are resolved and handover is complete, sign out of your account on a shared device. Follow the separate service-day procedure only if you are responsible for that review.'
],notes:[
 'This is a written operating checklist, not an automatic handover record or staff notification. Use your property’s approved communication method.',
 'Do not share passwords, guest identity documents or card details in a handover. If an unresolved request prevents a normal handover, ask the property administrator to reconcile it before clearing browser data.'
],keywords:['handover','end shift','shift change','cashier','pending request']},
{id:'repair-assistant',title:'Ask about unfinished maintenance',area:'Rooms',availability:'Release preview',steps:[
 'After the pending repair release and property assistant are activated, ask questions such as How many repairs are overdue? or How many repairs await verification?',
 'Read the returned counts and snapshot limitations. Counts cover the selected property’s unfinished repairs, not just the visible queue page.',
 'Open Rooms & housekeeping → Maintenance to inspect the repairs and take an authorized action. The assistant does not assign, cancel or complete repair work.'
],notes:[
 'Urgent, overdue, unassigned and awaiting-verification counts overlap. Completed and cancelled repairs are excluded. Due today is not overdue.',
 'If property access or repair data cannot be verified, the assistant reports unavailable information instead of zero. Room operations and repairs are read separately and can change between reads.',
 'The model selects fact definitions; displayed counts come from verified server data. Repair notes and property snapshots are not sent to the model. Do not put private guest details into your question.',
 'This describes unpublished functionality. It does not confirm that the hosted AI connection is active.'
],keywords:['repair','assistant','AI','overdue','urgent','manager attention','verification']},
{id:'repair-work-orders',title:'Report, assign and verify repairs',area:'Rooms',availability:'Release preview',steps:[
 'After activation, select the correct property and open Rooms & housekeeping → Maintenance. In Report a repair, choose a room or Common area / no room, enter Location and What needs repair?, choose Priority and select Report repair once. Wait for confirmation.',
 'Use Repair status, Repair priority and Assigned work together to find work. Assigned to me uses your signed-in account. Filters cover the full property queue; changing a filter or choosing Refresh repairs returns to the first page. Use Next repairs for more results.',
 'Under Work to review, choose Unfinished, Overdue or Unassigned. These views exclude completed and cancelled repairs and combine with the other filters. Overdue uses the property’s current date, not the device date. If no work appears, review all selected filters.',
 'Repair overview counts all unfinished repairs in this property, including urgent, overdue, unassigned and awaiting-verification work. Overdue means due before the property’s current date; due today is not overdue. Counts overlap, exclude completed and cancelled repairs, and do not follow queue filters. Use Refresh repair overview for a current snapshot.',
 'An owner or manager selects Update repair, chooses Assign repair, selects an eligible person under Assign to, optionally sets Due date, enters Work notes / reason and selects Save repair action. Assignment is offered for reported or assigned repairs.',
 'The assigned worker selects Start work, then Submit for verification when finished. Enter a work note for each action. Owners and managers must also be assigned to use these worker actions.',
 'An owner or manager reviews submitted work and chooses Verify completed repair or Return for more work. Managers can cancel unfinished repairs or reopen completed or cancelled repairs. Reopening clears the assignee; assign the repair again.',
 'To escalate or lower an unfinished repair’s priority, an owner or manager selects Change priority, chooses New priority, enters a reason and saves. The history records the old and new priority. This leaves the workflow status, assignment, due date and room readiness unchanged. If the save is interrupted, check or retry the saved action before starting another change.',
 'Choose View history for saved actions, reasons and times. History runs earliest to latest; use Next history page for longer records.',
 'If the repair queue fails to load, use Retry loading repairs to keep the same page and filters. Refresh repairs starts again from the first page.',
 'If action details fail to load, choose Refresh repair actions. It rereads the repair and your access and clears unsaved action selections and notes. Pending saved actions use the recovery controls instead.'
],notes:[
 'These controls are in the pending release; hosted acceptance is unfinished. This guide does not activate them on the live site.',
 'Reporting or completing repairs does not change room selling availability or cleanliness. Use separate dated maintenance closures when a room must be unavailable; confirm housekeeping readiness separately.',
 'Urgent is a triage label, not an emergency notification. The list is not ordered by urgency or due date. Select the priority filter to review urgent work.',
 'Selecting a room does not fill Location automatically. Do not include identity documents, passwords or payment details in work notes. Displayed history times use this device’s time zone.'
],keywords:['repair','work order','maintenance','technician','assign','verification','urgent']},
{id:'repair-save-recovery',title:'Recover an interrupted repair save',area:'Troubleshooting',availability:'Release preview',steps:[
 'Keep the same account, property and browser tab. An interrupted response does not prove the repair save failed.',
 'For a new report, select Check repair confirmation. For assignment or another action, select Check saved action.',
 'For a saved repair action, View saved repair history shows the original repair’s recorded actions, even if another repair is selected in the queue. Reviewing history does not resend the request or prove its result; use Check saved action for confirmation.',
 'If confirmation is not found, use Retry saved report or Retry saved action for the original request. Do not prepare a replacement merely because confirmation is missing.',
 'For an assignment or other repair action that you no longer want to submit, choose Cancel unsaved request. It keeps a change that already saved; otherwise it prevents that request from saving later. Wait for a verified result before preparing a new action. If confirmation is interrupted, repeat Cancel unsaved request for the same request.',
 'For a new report, Cancel unsaved report keeps a report that already saved or prevents the unsaved request from creating a repair later. Wait for confirmation before preparing another report. If the response is interrupted, repeat cancellation for the same saved report.',
 'Cancelling an unsaved request does not cancel the repair itself. Review current repair details before creating another action. If your access was removed or the saved request cannot be read, preserve the request and ask the property administrator to investigate.'
],notes:[
 'Recovery details are stored for this browser session. Closing the tab or clearing browser data can remove them. Do not clear data to bypass a pending save.',
 'The interface retains the original request and does not automatically resubmit it when reopened. A missing confirmation may still be in flight.',
 'Cancellation does not resolve an unreadable browser record or restore removed property access. These require administrator investigation.'
],keywords:['repair','retry','timeout','confirmation','interrupted','recovery']},
{id:'test-payment-recovery',title:'Review interrupted Stripe test payments',area:'Troubleshooting',availability:'Release preview',steps:[
 'After this release is activated, an owner or manager can open the reservation payment controls and find Interrupted test payments.',
 'Select Find requests to review. The list covers recorded unresolved payment operations for this reservation. Use Next requests when another page is available.',
 'Select Compare with Stripe test for the request being investigated. Wait for the review result and recorded time.',
 'If review confirmation was lost, select View saved reviews before running another comparison. Match the review time and reviewer reference. Use Next saved reviews for another page. Saved reviews are past observations, not the current Stripe status.',
 'If observations agree, the comparison matched at that moment. The interrupted operation still needs separate resolution; agreement does not close it.',
 'If the result changed, refresh and review again. If a session cannot be identified or observations need reconciliation, keep the existing checkout and ask the property administrator to investigate.'
],notes:[
 'This is a release preview for the configured Stripe test property. It does not collect money, issue refunds, adjust the guest bill or resolve interrupted operations.',
 'No requests found means no matching recorded unresolved operations were listed. It does not prove that no provider payment exists.',
 'Each successful comparison records the reviewing manager. A timeout can leave an audit record even when confirmation did not reach the screen.',
 'Do not create another payment solely because a search found no matching session. The provider search is bounded.'
],keywords:['test payment','recovery','interrupted','stripe','comparison','reconciliation']},
{id:'interrupted-guest-save',title:'Handle an interrupted guest save or test payment',area:'Troubleshooting',availability:'Release preview',steps:[
 'If the screen reports an unavailable service or an unconfirmed result, note the property, reservation reference, action and approximate time. A timeout alone does not tell you whether the save completed.',
 'For registration, reopen the original guest link to check its saved status. If the original form offers a retry, submit the same information. Do not create a new registration link or change the signature just because confirmation was delayed.',
 'For phone arrival details, refresh the existing reservation details to check what was saved. Keep the existing guest link while investigating.',
 'For Stripe test checkout, review the existing checkout and its status in the test provider account. Do not prepare another payment or record money received solely because the guest reports an error.',
 'If test cancellation is pending, an owner or manager should use Cancel / retry test checkout cancellation for that same checkout. A disabled guest link does not stop a checkout already opened with the provider.',
 'If cancellation reports that the checkout was paid, review the existing test payment. Cancellation is not a refund. Do not create a second payment to correct the status.',
 'If cancellation reports an error after the provider checkout expired, keep the same checkout and retry its cancellation after service resumes. Ask your administrator to review any result that remains unclear.',
 'If the result remains unclear, give your property administrator the reservation reference, action, time and visible error. Stop repeated attempts while an announced maintenance pause is active.'
],notes:[
 'Never include a full guest-link URL, password, card details, identity-document image or signature in an ordinary support message.',
 'Test payments do not settle a real guest bill. Registration signatures and phone arrival details do not automatically check a guest in.',
 'For AI help, an unavailable answer may still have used provider resources. Use the written guide and retain the request reference if shown; do not repeatedly submit new questions to work around a pending result.',
 'Maintenance recovery protections are in development. A successful retry does not itself clear an earlier unresolved operation; infrastructure recovery review remains separate from staff check-in.',
 'This chapter describes the release preview. It does not confirm live payment processing or a completed recovery service.'
],keywords:['timeout','unavailable','interrupted','retry','duplicate','payment error','registration error','maintenance']},
{"id":"property-staff-access","title":"Manage staff access by property","area":"Administration","availability":"Release preview","steps":["Activation pending: property-specific access is prepared for a future release and is not yet enabled on the live PMS.","After activation, select the intended property and open Staff access. In Organization staff, add or update a confirmed account as Staff or Manager. An account role sets the highest access level that its property assignments can use.","Select Open property access to verify your owner account. Find the employee; use Next page when needed. Owners retain access to all properties and cannot be changed through these controls.","Choose Change access, select No access, Staff or Manager, and enter a Reason for change. Manager is offered only for an organization Manager account. Select Save property access once and wait for Property access saved.","If the result is interrupted, Retry same change resends the same request. Refresh current access loads the current assignments for review before another edit. A stale change cannot overwrite a newer decision.","Choose History beside an employee to review access changes, reasons, account attribution and times. Older changes opens the next page; Latest history returns to the newest records. The displayed times follow this device's locale.","Choose No access to remove access to this property. Remove access in Organization staff removes access to the entire organization. Check the scope carefully before saving."],"notes":["The transition is designed to preserve reviewed existing access. New properties and newly added staff require explicit assignments after activation.","Removing property access does not erase past audit records. Review existing housekeeping assignments and cashier responsibilities when changing access.","Signing out closes the property controls. Sign in and verify the intended owner account before reopening them.","These instructions describe the release preview. Database activation and live acceptance testing remain pending; the current organization-wide access model is not changed by opening this manual."],"keywords":["staff","owner","manager","permissions","property access","remove access","audit history","retry"]},
{"id": "digital-registration", "title": "Prepare, sign and review guest registration", "area": "Guests", "availability": "Release preview", "steps": ["Activation pending: these registration controls are not yet available in the live PMS. Use this chapter for training after the property has activated and tested registration.", "After activation, an owner or manager opens Property settings, finds Registration documents and selects Open registration controls. Enter Document title and Registration text, choose Review document, check the exact text and select Publish this version. Publishing revised text creates a separate version; previously signed text is preserved.", "Open the reservation, choose Digital registration and then Open registration controls. Choose Create guest link, load the published documents, select the correct version and create the link once. Link creation does not send a message automatically.", "The guest opens the link and checks the electronic registration card: property, guest name, arrival and departure dates, room type, and guest count. The snapshot reflects the reservation at link creation and is bound to the signature. If any detail is wrong, contact the property to correct the reservation and issue a new link; do not sign inaccurate details.", "Read the property-published document, enter the signing name and either draw a signature or select Type my signature instead of drawing. With the typed option, the entered name becomes the electronic signature. Confirm you reviewed both the stay details and registration document, then select Sign registration. Wait for the saved confirmation.", "If saving is interrupted, retry the same submission. Reopening a successfully signed link shows its saved status instead of asking for another signature. Do not create another request just because a response was delayed.", "Staff open Registration history, select the record and Load registration details to review the stay snapshot, exact document and saved signature. Typed signatures are labelled Typed electronic signature; drawn signatures show the saved drawing. The original issuing staff member can Recover existing guest link while the request is active and unsigned; this retains its original expiry.", "To stop guest access, enter the Reason for revoking and select Revoke guest link. Refresh and verify the result. Revocation preserves the saved signature, stay snapshot and document.", "Owners and managers can Load access history to see staff account IDs and access times, oldest first. Use Load more access history for additional entries."], "notes": ["Signing does not collect payment, check the guest in or provide a room key. Complete those tasks through their separate workflows.", "Links currently expire 24 hours after issue. Link expiry and revocation do not delete the registration record. Typed signing is available in this preview as an alternative to drawing. Keyboard, screen-reader and device acceptance, plus document retention setup, remain required before launch.", "The stay snapshot contains guest name, property, dates, room type and guest count. It excludes room number, price, contact, identity and payment data. Snapshots cannot be changed after link issue; the signature binds to its hash.", "If Guest signing is not activated yet appears, ask the property administrator to complete activation. Do not create substitute requests or send an unverified link. Existing registration records can still be reviewed when staff access is configured.", "Only the original issuing staff member can currently recover the existing link. Ask that person to recover it; do not change the guest or create duplicate requests to bypass the restriction.", "The preview includes the PMS controls and has passed local browser-to-database signing and reload checks. It is not yet activated on the live site; hosted setup and physical-device acceptance remain pending."], "keywords": ["registration", "signature", "sign", "guest link", "recover link", "revoke", "access history", "electronic registration", "typed signature", "type my signature"]},
 {"id": "ota-connections", "title": "Configure OTA delivery and review booking exceptions", "area": "Distribution", "availability": "Release preview", "steps": ["Select the correct property and open Connections. Owners configure connections; managers can review connections and delivery exceptions.", "Use the property and connection identifiers supplied by the approved OTA sender. Keep existing PMS means review only; select iRatePilot PMS as inventory authority only after agreeing the cutover with the property.", "Map each OTA room ID to the matching room type in this property. Enter the shared signing secret supplied through your secure setup process.", "Select Save disabled connection. Saving an existing connection also disables receiving. Verify mappings and inventory before selecting Enable receiving.", "Review Reservation delivery review. Check the booking, version, result and reason. Historical entries are not the current booking state.", "After correcting capacity, use Recheck capacity when available. This repeats validation; it cannot force a booking into sold-out inventory. Other exceptions need a corrected OTA event or reconciliation.", "Use Refresh to obtain current connection and delivery information. If an action has an uncertain result, review the saved state before repeating it. Reopen Connections if your signed-in account changes.", "For third-party setup, an owner may add or update a disabled provider channel with the OTA property ID and three-letter currency, then save external IDs for each PMS room type and active rate plan. Managers may review mappings but cannot edit them. Do not enter provider API secrets in these forms."], "notes": ["Receiving enabled is a configuration state, not proof of successful end-to-end OTA delivery or certification. Verify a real approved test delivery before launch.", "Connection identity cannot be reassigned to another property. Blank replacement secret keeps the existing secret; secrets are not shown in listings.", "The iRatePilot.com booking-receiver path has local end-to-end test evidence; verify the hosted migration, property mapping and controlled live booking before relying on it at a hotel.", "The outbound iRatePilot.com availability/rate worker is implemented in source but is not activated in the hosted system. Do not treat it as live inventory sync.", "Expedia, Booking.com, Agoda, Google Hotel, Airbnb and other external channels remain certification-pending. Each requires its own approved adapter, partner access, property/rate mapping and end-to-end certification.", "These controls cover the iRatePilot OTA sender connection. Other OTA, payment, lock, POS and accounting providers require separate setup and testing."], "keywords": ["OTA", "connections", "distribution", "room mapping", "inventory authority", "delivery review", "recheck capacity", "signing secret"]},
 {"id":"integration-readiness","title":"Understand integration readiness and next steps","area":"Connections","availability":"Release preview","steps":["Choose the property and open Connections. Scroll to Other property integrations below OTA setup.","Find the integration you need and read its status label and current-state note. Architecture only means a contract or design exists but the vendor is not connected. Development only means a partial local feature exists without an active provider. Provider adapter not implemented means there is no adapter to connect that vendor category yet.","Read the Next launch gate for the work needed to advance that integration. Depending on the category, this can include choosing a vendor, secure credential setup, partner approval, property and room mapping, sandbox testing, certification, and an end-to-end hotel test.","Treat the cards as a release-readiness summary. They do not test a vendor connection, send a message, accept a payment, issue a key or change property data.","Before staff rely on an integration, an owner should verify the approved provider, complete a controlled test round trip, check the returned status in the provider and PMS, and record the hotel’s acceptance."],"notes":["The current local catalog covers 14 non-OTA integration areas. Its labels summarize implementation evidence; they are not live health signals. No external provider is connected by the catalog.","OTA channel setup has separate provider and delivery status. A saved mapping or enabled switch is not proof of provider approval, certification or successful reservation delivery.","Never paste passwords, API keys, card data, identity images or door credentials into general notes or an unapproved integration form. Use the provider’s approved secure setup flow.","This guide topic and the readiness cards are in the local release preview until the PMS site is published and the provider workflows are individually implemented and accepted."],"keywords":["connections","integration","readiness","provider status","adapter","marketplace","launch gate"]},
{"id": "assistant-help", "title": "Ask the PMS assistant and recover an interrupted question", "area": "Help", "availability": "Release preview", "steps": ["Open Help & manual for the property you are working on. AI help requires an enabled connection; use the written guide when it is unavailable.", "Choose Operating instructions for how to use the PMS, or Current property for supported room-readiness and current stay counts. Ask “How many arrivals today?” for the current count of confirmed arrivals. Ask “Which rooms are dirty?” to see dirty room labels. Ask “What requires manager attention today?” for server-derived arrival, departure, housekeeping, maintenance and repair items. Ask “Which rooms are out of order?” to see rooms with an active maintenance closure on the property business date; confirm the closure dates in Maintenance because this answer does not independently certify physical room condition. Ask “What is tonight’s occupancy?” for current booked commitments against effective sellable capacity, when every room type has capacity configured. Ask “What is tomorrow’s forecast?” to see tomorrow’s currently booked commitments against effective sellable capacity; it is not an AI demand or revenue prediction. When the balance-report connection is available, an owner or manager can also ask which reservations have a positive current guest balance. Owners and managers can ask about seven-day channel booked value; these figures are known accommodation booked value for scheduled arrivals, not earned revenue, collected payments, settlement or profit. Owners and managers can also ask why a saved rate decision changed a nightly price; the assistant shows the saved, human-approved explanation when available.", "For operating instructions, expand Source instructions and verify the guidance before acting. For property answers, check the property date, time zone, snapshot time and whether the displayed facts answer your question.", "For a balance answer, review the listed reservation reference, status, stay dates and amount, plus any unknown-balance count. Check the individual folio before follow-up; a positive balance is not automatically overdue or collectible.", "If the answer times out, select Check last question status. This checks the existing request without sending another question. If its outcome is unconfirmed, use the written guide instead of repeatedly submitting.", "Owners and managers can select Refresh usage in AI usage history to review recorded request status and reported tokens. Use Older requests for earlier records."], "notes": ["This preview cannot perform hotel actions. Tonight’s occupancy answer means current reservations committed against effective sellable capacity; it is not a demand forecast or a reconstruction of actual occupied rooms. Tomorrow’s booked occupancy is also a current reservation snapshot; it is not a predictive demand or revenue forecast. The percentage is unavailable if any room type lacks configured capacity or total sellable capacity is zero. Manager-attention items are compiled from separate current snapshots and may change before you act. Balance amounts can be unknown, and the balance report and room-operations facts are separate snapshots. A positive balance does not prove payment settlement. Ready rooms still require availability checks for the requested stay dates.", "The AI provider receives the question and available fact definitions, not reservation references or balance amounts. Do not include guest names, document images or numbers, card details, passwords or other private information.", "A completed request does not mean its answer can be restored: answer text is not retained here. Failed or interrupted requests may still incur provider usage. Unknown usage is not zero."], "keywords": ["AI", "assistant", "question", "timeout", "status", "instructions", "tokens", "recovery", "unpaid balance", "guest balance", "tonight occupancy"]},
{"id":"split-folios","title":"Separate charges with split folios","area":"Finance","availability":"Release preview","steps":["Open Reservations, choose the correct stay, and select Manage stay or Check in / prepare. Open View reservation folio and confirm the guest, property, dates, currency and current balance.","Find Split folios below the main folio. Review each folio balance and select Refresh split folios before making a financial entry.","As an owner or manager, select Add a folio, enter a clear name such as the approved company or group name, choose its type, then select Add folio. Confirm it appears in the folio list.","To record an item, select the destination Folio and Entry type. Enter the amount, distinct reference and reason. Select the required review checkbox, then record the entry once. Refresh and verify the selected folio and combined reservation balance.","To move an existing charge between folios, use Route a charge. Choose the original charge, destination folio, amount and reason, then select Route charge. Confirm the source reversal and equal destination charge in Folio entry history.","For an uncertain result, use Check saved request or Refresh split folios. Retry only the exact saved request shown; do not create a replacement entry while its result is unresolved."],"notes":["Staff can read split-folio balances and history. Only owners and managers can add folios, post entries or route charges.","Routing creates a linked reversal and equal charge. It changes which folio holds the charge but does not change reservation totals or collect or transfer money.","Payment received (record only) and Refund issued (record only) document an external transaction that has already happened. They do not charge a card, issue a refund or prove processor settlement. Use the configured payment provider workflow to collect or return money, then record its reference only after verifying the provider result.","Entries are audited and append-only. Correct a mistaken charge with a charge reversal against that exact charge. Reduce an overstated payment record only when no real refund was issued. An opening stay charge reversal requires itemized invoice reconciliation; stop and ask an owner or manager to review its categories.","This is a release preview until the split-folio database migration is installed in the hosted PMS and the authenticated owner, manager and staff workflows are verified. If accounts or balances cannot load, do not post or retry a financial entry."],"keywords":["split folio","split folios","company folio","group folio","route charge","payment record","external payment","folio account"]},
{"id": "folio-correction", "title": "Correct an overstated payment or charge", "area": "Finance", "availability": "Release preview", "steps": ["Open the reservation folio and select Refresh folio. Review Entry history and the supporting transaction record.", "As an owner or manager, use Record an entry. For an overstated payment record where no money was refunded, select Payment record reduction. For an incorrect charge, select Charge reversal.", "Under Apply against, choose the exact original payment or charge. Opening stay charges are not available in this form; an opening-charge reversal requires itemized invoice reconciliation by an owner or manager.", "Enter the positive correction Amount (USD), a distinct Transaction / document reference, and Reason. Check the confirmation that matches what actually happened, then record the entry once.", "Review the refreshed entry history and balance. If the result is uncertain, Refresh folio to look for its receipt or use Retry this exact request."], "notes": ["A payment record reduction does not return money. A charge reversal reduces recorded charges; it does not refund a payment.", "The original entry remains in the history. Do not create a fictional payment or refund to force a balance. If reservation amounts changed after the folio opened, review the difference and document the appropriate adjustment."], "keywords": ["payment correction", "overstated", "mistake", "charge reversal", "reduce payment"]},
{"id": "folio-refund", "title": "Record a refund already completed outside the PMS", "area": "Finance", "availability": "Release preview", "steps": ["Confirm the actual refund in the external payment record under your property procedure. Open and refresh the reservation folio.", "As an owner or manager, select External refund record under Entry type.", "Under Apply against, select the original recorded payment. Enter the Amount (USD), the external refund Transaction / document reference, and Reason.", "Confirm I verified this transaction in the external payment record, then record the refund once.", "Verify the refund entry and resulting balance. For an interrupted response, use Refresh folio or Retry this exact request before considering another entry."], "notes": ["This form records an external refund; it does not send money through Stripe, a bank or a card terminal.", "Use Guest cash payments for cash returned through your open drawer. Security deposit and company account refunds have separate workflows."], "keywords": ["external refund", "return money", "card refund", "folio refund"]},
{"id":"stripe-test-refund","title":"Issue or recover a Stripe test refund","area":"Finance","availability":"Release preview","steps":["Open the reservation's guest pre-check-in section and confirm the original Stripe TEST payment is complete and has been reconciled to the folio.","As an owner or manager, choose Issue / recover full Stripe test refund. Enter the reason and confirm that you want to refund the complete test payment.","If Stripe reports a pending result, choose the same action again later to check the saved provider refund and finish folio reconciliation.","Refresh the folio and confirm one external-refund entry is linked to the original Stripe test receipt."],"notes":["This workflow uses Stripe TEST credentials only. It cannot refund a live charge or return real money.","Only one full refund per test payment is supported. Partial refunds, live refunds, chargebacks, and processor settlement reconciliation are not available in this workflow.","The PMS saves the owner/manager, entered reason, provider refund ID, status and folio link for retry safety. Review Stripe test mode if the result is uncertain."],"keywords":["stripe test refund","test refund","refund payment","refund retry"]},
{"id": "cash-payment", "title": "Record cash received or refunded through your drawer", "area": "Finance", "availability": "Release preview", "steps": ["As an owner or manager, open your cashier drawer and open the guest folio. Under Guest cash payments, select Load cash payments.", "Choose Cash received or Cash refunded. For a refund, select Original cash receipt with sufficient refundable balance.", "Enter Cash amount (USD), Cash receipt reference and Cash transaction reason. Select Review cash transaction.", "Verify the actual physical cash exchange. Check I verified this actual cash exchange, then select Record cash transaction / retry.", "If the response is interrupted, select Check cash transaction result. Keep the saved request and retry only the same exchange if no receipt is found.", "After success, load cash payments again before starting another transaction."], "notes": ["This records physical cash through your own open drawer and does not process a card payment. Do not hand over or receive cash a second time just because a response was interrupted.", "Cancel saved cash request concerns an unrecorded request. It does not reverse a recorded payment or undo a physical cash exchange. Reconcile the actual cash before cancelling."], "keywords": ["cash", "drawer", "cash refund", "cash receipt", "retry payment"]},
 {id:'guest-records',title:'Create or update a guest profile',area:'Guest records',availability:'Release preview',steps:['Open Guest records in the selected property. Search for the guest before creating another profile.','Select an existing profile to edit it, or use Create guest profile for a new guest. Review the contact fields and select Save guest profile.','On a saved profile, choose View stay history to load its past and upcoming stays at this property. Choose Load older stays to page through more results; use Refresh history to reload the latest records.','To review or update the exact details recorded on one stay, open that reservation and choose Guest contact & billing.','Verify the saved confirmation. Use Create a different guest profile when you need a separate record.'],notes:['Reusable profiles and this history view are scoped to the selected property. Profiles are not centrally shared across properties.','Linking a profile to a stay requires a separate review. Changing a profile does not rewrite contact details already recorded on existing stays.','If a save is interrupted, use the saved guest request recovery controls before another edit.','The history API migration must be installed on the connected hotel service before this release-preview feature can load in a hosted workspace.'],keywords:['guest profile','contact','guest name','email','phone','personal information','stay history']},
 {id:'security-deposit',title:'Record refundable security funds',area:'Finance',availability:'Pilot workflow',steps:['Open the reservation and select Security deposit record. Review existing entries and original receipt balances before adding a record.','As an owner or manager, choose the Security-deposit entry type. For a return or receipt correction, select Original received deposit.','Enter Security amount (USD), the external method when requested, Deposit document reference and Deposit record reason. Select Review deposit entry.','Verify the external receipt or refund evidence, or confirm that a correction involved no money movement. Select Confirm security-deposit entry.','Verify the result. Use Export deposit history CSV for the current record, or Check saved deposit request if the save result is uncertain.'],notes:['This records money received or returned outside iRatePilot. It does not collect money, reduce the guest bill or change revenue. Card authorization holds are not received funds.','A receipt reduction corrects a mistaken receipt record; it is not a refund. Do not enter a fictional receipt to balance a mistake. Applying security funds to a bill and correcting mistaken refunds need separate workflows.','An ended stay with remaining security funds needs review of external records; the message is not authorization to refund.'],keywords:['refundable deposit','security funds','damage deposit','receipt reduction','deposit refund']},
 {id:'balance-follow-up',title:'Schedule staff follow-up on an unpaid balance',area:'Finance',availability:'Pilot workflow',steps:['Open Balance follow-up from the reservation, or use the Balance follow-up workspace to find an existing task.','Review Current account and any message that the balance or booking changed since the last action. Security funds are separate.','As an owner or manager, choose the available Follow-up action. Enter Staff follow-up date when requested and Reason for this action.','Select Review follow-up action, verify the current account and intended action, then confirm the checkbox and Confirm follow-up action.','Review the saved state and Follow-up history. If confirmation is interrupted, use Check saved follow-up request before Retry exact follow-up request.'],notes:['A staff follow-up date is not a payment due date. Review completed does not mark the stay paid, collect money or send a guest message.','Stop follow-up ends the staff task; it does not waive the balance. Stop future retries concerns an unresolved request and does not undo a recorded action.'],keywords:['unpaid','balance follow up','collection','reminder','review completed']},
 {id:'amend',title:'Change a confirmed reservation',area:'Front desk',availability:'Pilot workflow',steps:['Open the reservation and select Edit reservation when available.','Review Guest name, Room type, Arrival, Departure and Guests. Enter the full Accommodation (USD) and Taxes (USD) amounts for the revised stay.','Review any retained hotel fees and select Save reservation changes. Every stay night is checked again.','Open the reservation folio and reconcile any difference between the revised booking and posted charges.'],notes:['This form is for eligible confirmed reservations. iRatePilot OTA reservations cannot be changed here.','Date changes do not automatically recalculate retained hotel fees. Opened folios keep their posted charges, and amount changes may require manager approval and an adjustment. No payment is captured or refunded.','Reload latest reservation and discard these edits replaces unsaved edits with the current reservation.'],keywords:['edit reservation','change dates','modify booking','amend']},
 {id:'extend',title:'Extend an in-house stay',area:'Front desk',availability:'Pilot workflow',steps:['As an owner or manager, open the in-house reservation and select Extend stay.','Review the current departure and select New departure. The guest keeps the same room.','Enter New total accommodation (USD) and New total taxes (USD) for the full revised stay, including the nights already booked. Enter the reason.','Review retained hotel fees, confirm the review checkbox and select Extend stay.','Verify the new departure and reconcile the folio. If the result is uncertain, use Retry this exact extension.'],notes:['Extra nights do not automatically add hotel fees or change posted folio entries. No payment is collected by extending a stay.','OTA changes must be made at their source. Availability and room conflicts may prevent an extension.'],keywords:['extra night','late departure','extend stay','overdue']},
 {id:'room-move',title:'Move an in-house guest to another room',area:'Front desk',availability:'Pilot workflow',steps:['As an owner or manager, open the in-house hotel reservation and select Move room.','Select Refresh rooms for move and review the current room.','Choose a clean Destination room of the same booked type, enter Room move reason and confirm the review checkbox.','Select Confirm room move. Verify the new assignment and coordinate keys through the property lock procedure.','If confirmation is interrupted, use Check saved room move before Retry exact room move.'],notes:['The old room becomes Dirty. Prices and stay dates stay unchanged; moving a room does not extend an overdue stay.','Destination rooms must have no open turnover task, occupancy conflict or overlapping maintenance. Future conflicts are checked again when saving. Whole-home moves and room-type upgrades are not part of this workflow.'],keywords:['room transfer','move room','change room','keys']},
 {id:'cancellation',title:'Cancel a reservation that has not started',area:'Front desk',availability:'Pilot workflow',steps:['Open the eligible confirmed direct or imported reservation and select Cancel reservation….','Review the current stay, released nights, financial information and service-allocation warnings. Use Review reservation folio or Review service-day allocations when needed.','Enter Cancellation reason, confirm that the stay never started and that you reviewed the separate financial decisions, then select Confirm cancellation.','Verify the saved cancellation. If the result is uncertain, use Check saved cancellation request before Retry exact cancellation request.'],notes:['Cancellation releases inventory but does not automatically waive charges or refund money. Handle the financial decision separately under the property procedure.','Use the original saved request when recovering an interrupted response. Do not create a replacement booking while its result remains unclear.'],keywords:['cancel booking','cancellation','refund','release rooms']},
 {id:'no-show',title:'Review a guest who did not arrive',area:'Front desk',availability:'Pilot workflow',steps:['As an owner or manager, open the eligible direct or imported reservation and select Review no-show.','Review the property date, reservation status, charges, recorded payments, balance and listed blockers.','Review reservation folio and service-day allocations separately.','When eligible, enter No-show review reason, confirm that the guest never started the stay and select Mark as no show.','If confirmation is interrupted, use Check saved no-show request before Retry exact no-show request.'],notes:['The current workflow permits marking only once the scheduled departure date has arrived. It is not an automatic first-night no-show process.','This is a terminal cancellation disposition. A later arrival needs a new reservation checked against capacity. No-show marking does not add fees, waive charges, refund money or close a service day.'],keywords:['no show','did not arrive','missed arrival']},
 {id:'groups',title:'Book a group and manage its rooming list',area:'Reservations',availability:'Pilot workflow',steps:['Open Reservations, then Group bookings. Owners and managers can choose New group booking.','Enter the group name and stay dates. For every room, enter the guest name, room-type rate plan and guest count.','Select Review group prices. Review every room, taxes and fees, then confirm and select Book all rooms.','Open the saved group to view the rooming list. Select a guest to assign a room, prepare check-in or review the individual reservation and folio.','If booking confirmation is interrupted, use Retry saved group booking for the original request.'],notes:['Quotes expire after 15 minutes. Availability is checked again when booking; if any room cannot be booked, none of the rooms in that request are saved.','Each room has its own reservation. Booking the group does not collect payment; stay value is not the unpaid balance. Cancel individual stays through their cancellation review.','Room blocks and bulk group changes are not available in this workflow. Company billing is documented separately as a release preview.'],keywords:['group booking','rooming list','multiple rooms','group reservations']},
 {id:'service-close',title:'Review and close a service day',area:'End of day',availability:'Pilot workflow',steps:['Open Service-day close and verify the property and Next service day. If no ledger exists, the organization owner chooses First service date, enters a Starting-date reason and confirms Start service ledger.','Select Refresh preview. Resolve each item under Before closing: unresolved arrivals, overdue stays, missing allocations or changed charges must be reviewed in the relevant workflow.','Use Review allocation when a stay needs its charges assigned to service nights. Reconcile the full stay amount and preserve previously closed amounts.','Review inventory figures, allocation totals and signed corrections. Blocked rows are excluded from the displayed partial totals.','When Ready for review is shown, confirm the review checkbox and select Close service day for the displayed date. Verify the confirmation and next service day, then review the preserved closed report.'],notes:['The ledger advances one closed day at a time. Starting it does not backfill earlier history. A service day must have finished in the property time zone before it can close.','This workflow allocates nightly revenue; it does not collect payments, change folio balances or replace general-ledger and settlement accounting. The front-desk calendar still follows the property time zone.','If charges changed after closing, use Review changed charges to review a forward correction; do not rewrite the original closed report.'],keywords:['night audit','end of day','close day','unresolved arrivals','allocation','revenue']},
 {id:'cashier-open',title:'Open a cashier drawer',area:'Cashier',availability:'Pilot workflow',steps:['Open Reports and choose Active cashier drawers from Report group.','Under Open your cashier drawer, select Load opening workspace. Enter Drawer name and the physically counted Opening cash (USD), then Review opening.','Verify the saved drawer and amount, select the confirmation checkbox and Confirm opening / retry.','After confirmation, select Load active drawers to view your session.','If the response is uncertain, use Check opening result before retrying the saved request.'],notes:['Staff see their own drawer; owners and managers can see active drawers for the property.','Opening cash is a cash count, not a guest payment. Do not record it again as a guest receipt.','Resolve any saved opening before creating another. Cashier activity may be paused by an owner.'],keywords:['drawer','cash','opening float','shift','cashier']},
 {id:'cashier-close',title:'Count cash and close a cashier drawer',area:'Cashier',availability:'Pilot workflow',steps:['In Reports, choose Active cashier drawers, select Load active drawers and Review for the intended drawer.','Physically count the cash. Enter Counted cash (USD) and select Review cash count.','Compare Expected cash, Counted cash and Over / short. Investigate differences and record an accurate Closing explanation.','Select Prepare closing confirmation, review the saved count and explanation, select the confirmation checkbox and Confirm drawer close / retry.','Verify Drawer close confirmed. Reload active drawers and use the Cashier closings report group to review the closing record.'],notes:['Review cash count does not close the drawer. If the response is uncertain, use Check closing result to recover the saved close.','Closing a drawer does not close the service day or reconcile the bank. These are separate operations.','Receipt recovery and drawer closing remain available while new cashier activity is paused.'],keywords:['cash over','cash short','variance','end shift','closing','cash count']},
 {id:'room-setup',title:'Add and manage physical rooms',area:'Property setup',availability:'Pilot workflow',steps:['Select the correct property and confirm it is a hotel. As an owner or manager, open Property settings.','Under Room types, choose Add type only when the required category is missing. Enter its name and maximum guests, then save. Existing type names and guest limits are not edited from this screen.','Under Physical rooms, choose Add room. Select the room type, enter the room number or label exactly as staff should see it, and save.','Check the new room in the Property settings list and Today room rack. Confirm the total room count and the room type before using it for a reservation.','To correct a room number, choose Edit room label beside the room, enter the corrected label, and select Save room label. Refresh the workspace and verify the saved number.','To remove an unused test room, choose Remove room, type its displayed label exactly, and select Confirm remove room. Review the updated room count and sellable capacity afterward.'],notes:['Only owners and managers can change room setup. The Remove room action removes a room from this property; it is rejected when the room has history, when active stays remain in the room type, or when future sellable inventory would exceed the remaining physical rooms.','Do not remove or rename a room that a guest is currently using. Check reservations, housekeeping and maintenance before changing its number. A room-type change is not offered by the room-label editor.','Sample inventory is for testing only. In the Red Roof Inn Ridgeland test property, labels 301–367 are sample rooms that have not been verified against the hotel’s approved room map. Replace or correct them before operating real hotel stays.'],keywords:['add room','physical room','room setup','room type','edit room number','remove room','sample room','property settings']},
 {id:'inventory',title:'Configure availability and resolve missing capacity',area:'Property setup',availability:'Pilot workflow',steps:['Select the correct property. In Property settings, create the room types and physical rooms first.','As an owner or manager, open Inventory and select Set inventory. Choose the room type, First sellable night and End date (exclusive).','Enter Total units available for sale per night as the selling ceiling for that room type, not the number currently left after bookings.','Review Configured ceiling, Physical units, Closed units, Effective units, Reserved and Available for the stay nights.','If booking reports Capacity is not configured, configure every missing stay night, then obtain a fresh quote.'],notes:['The end date is not a sellable night in this range. For September 10 through September 12 nights, use September 13 as the end date.','Effective capacity is limited by physical rooms and dated maintenance closures. Existing reservations reduce available units; do not subtract them again when setting the ceiling.','A whole-home property uses 1 to open the entire home or 0 to close it. Existing reservations are protected. A clean room card does not replace nightly capacity configuration.'],keywords:['14 rooms available','capacity is not configured','inventory','selling ceiling','unavailable']},
 {id:'rates',title:'Set room prices and resolve No active plan',area:'Property setup',availability:'Pilot workflow',steps:['As an owner or manager, open Rates & plans and create a rate plan for the intended room type. Enter Plan name and review its taxes and fees.','Select Active for new quotes and Save plan. For an existing plan, select Edit plan, review its settings and save.','Under Set nightly prices, select the Rate plan, First night and End date (exclusive). Enter Room price per night before taxes & fees (USD), then Save nightly prices.','Use Nightly price schedule to verify that every stay night has a price. The schedule dates control the displayed range.','Return to the booking, select the matching room type and refresh the quote to use the new pricing.'],notes:['An active plan and nightly prices are separate requirements. Creating or activating a plan does not fill its nightly prices.','No active plan means the selected room type needs an active plan; also verify you are in the correct property.','Saving nightly prices replaces prices for the selected plan and date range. Older quotes must be refreshed. Refresh / discard edits discards unsaved plan edits.'],keywords:['automatic rate','no active plan','nightly rate','edit plan','price']},
 {id:'revenue-demand-calendar',title:'Record event and seasonal demand inputs',area:'Property setup',availability:'Release preview',steps:['As an owner or manager, open Rates & plans and find Events & seasonal demand inputs. If this card is not visible, the feature is not activated for your property.','Select Manage calendar. Wait for the saved property settings to load before editing.','Choose Local event or Seasonal period, enter a short name, an inclusive start and end date, and a demand adjustment from -50.00% to +100.00%. Select Add input.','Review each draft row. Select Remove to delete a row from the draft, then select Save demand inputs to save the complete calendar as a new property version.','If the save is interrupted, use Retry same save or Refresh saved settings. Do not create a replacement save while the first result is uncertain.'],notes:['These are manager-entered inputs, not verified event demand or an imported calendar. The stored adjustments are not yet applied by a PMS forecast screen and never change nightly prices automatically.','Each save is property-scoped and versioned. Only owners and managers can edit it; staff may not change the calendar.','The supported limit is 25 events and 12 seasonal periods per property. Each date range is at most 367 inclusive calendar dates.'],keywords:['event','seasonal','demand input','calendar','forecast','revenue']},
 {id:'rate-plan-booking',title:'Book a reservation from a rate plan',area:'Reservations',availability:'Pilot workflow',steps:['Open New reservation and choose Book from a rate plan. Select the room type, arrival, departure and guest count. The active plan for that room type is selected automatically.','Wait for the saved nightly price, taxes and fees to load for each stay night. Change the dates or room type and review the refreshed quote; select Refresh price if needed.','Review every night and the stay total, then enter the guest name and check I reviewed these stay dates and charges. Select Book this quoted stay once.','Wait for the saved reservation confirmation. The booking creates a confirmed reservation; it does not collect payment or assign a physical room. Open the reservation later to assign a room and complete guest check-in.','If the form says Capacity is not configured on a date, note the date and open Inventory for the same property. Select Set inventory, choose the matching room type and configure a range that includes every missing stay night.','Enter the total units available for sale per night as the selling ceiling, then review physical, closed, effective, reserved and available units. Save the inventory and reopen a fresh quote.','If the selected room type has no active plan or a night has no price, open Rates & plans, activate the correct plan and save nightly prices covering each stay night. Reopen the booking form and review a fresh quote.','If booking confirmation is interrupted, retry the exact saved request. Do not start another booking until the original result is reconciled.'],notes:['The departure date is the checkout date and is not a sellable night. Inventory date ranges use an exclusive end date; include the last sellable night before that end date.','A quote expires after 15 minutes and does not hold inventory. Saving rechecks the quote and available capacity.','The room-price quote automatically includes saved taxes and applicable hotel fees. A booking quote is not a payment authorization or receipt.','Physical rooms and active maintenance closures limit the sellable ceiling. Do not add sample capacity to an operating hotel or count the same reservation twice.'],keywords:['new reservation','rate plan','book this quoted stay','capacity is not configured','missing capacity','refresh price','availability','booking confirmation']},
 {id:'taxes-fees',title:'Configure City, State, Lodging, Resort and Technology charges',area:'Property setup',availability:'Pilot workflow',steps:['In Rates & plans, create a plan or select Edit plan.','Under Taxes, enable the applicable City, State and Lodging categories and enter their approved percentages.','Under Optional hotel fees, enable Resort or Technology as needed. Enter each fixed USD amount and choose Per night or Per stay.','Under Taxes on this fee, select the tax categories that apply to that fee. Verify those taxes are enabled.','Save plan, obtain a fresh booking quote and review the room price, taxes, fees and total before booking.'],notes:['No jurisdiction rates are supplied automatically. Use the settings approved for your property.','Each enabled tax applies to the room price. Taxes are separate, without compounding, and rounded to cents for each night. A per-stay hotel fee is charged on the first night.','If a previous combined tax appears, disable it when separate taxes replace it so you do not apply both. These controls do not support every possible jurisdiction calculation.'],keywords:['city tax','state tax','lodging tax','resort fee','technology fee','combined tax']},
 {id:'rate-package',title:'Add included services to a rate plan',area:'Property setup',availability:'Pilot workflow',steps:['As an owner or manager, open Rates & plans and find the rate plan.','Expand Edit package inclusions and enter the services included with this rate, such as breakfast or parking. Do not include guest identity data or payment details.','Select Save package details. If confirmation is interrupted, use Retry saved package update; it checks the request receipt and retries the same request.','Open the guest booking quote and confirm the included package text appears before booking. Review the nightly rate and taxes.'],notes:['Package text is descriptive and is snapshotted into new quotes and reservations. It does not create a separate charge, service order, inventory reservation or tax rule. Increase the nightly rate yourself to include package costs.','Existing quotes retain the package details captured when they were created. Obtain a fresh quote after changing a plan. A package description is not an OTA add-on integration.'],keywords:['package','breakfast','included services','rate plan','retry']},
 {id:'cleaning-fee',title:'Set a whole-home cleaning fee',area:'Property setup',availability:'Pilot workflow',steps:['As an owner or manager, open Property settings and review the current property model and cleaning-fee settings.','For a Whole-home vacation rental, select Enable Cleaning fee and enter Cleaning fee amount (USD).','Choose the applicable categories under Taxes selected for Cleaning, then Save cleaning-fee settings.','Obtain a fresh quote and review the once-per-stay charge.','If confirmation is interrupted, use Check saved cleaning-fee request before Retry exact cleaning-fee request.'],notes:['Only whole-home properties can enable Cleaning. Disable it before converting a home to a hotel.','Saved bookings retain their original charges. Disabled settings retain the amount and tax selections.'],keywords:['cleaning fee','vacation rental','whole home','retry']},
 {id:'shift',title:'Start your shift',area:'Front desk',availability:'Pilot workflow',steps:['Select the correct hotel or home in PROPERTY. Check the property name and business date.','Open Today to review rooms, arrivals, departures and rooms to prepare.','Use Refresh workspace when you need the latest available data.'],notes:['The visible workspace refreshes every 60 seconds and when the browser regains focus. Instant event-driven synchronization is not yet implemented.'],keywords:['today','dashboard','refresh','property']},
 {id:'document-scan-recovery',title:'Scan a guest document and recover a stalled read',area:'Front desk',availability:'Release preview',steps:[
 'In the walk-in guest form, choose Open camera or Upload a photo. Use a clear JPG, PNG or WebP image up to 15 MB. Keep the full document visible; for passports include the bottom machine-readable lines.',
 'With the camera open, hold the document steady. Auto-scan when clear and steady attempts a read automatically. Read ID now also starts a capture. Use Camera or Switch front / rear to choose another camera.',
 'If automatic scanning pauses after repeated unsuccessful reads, reposition the document and turn Auto-scan when clear and steady on again, or capture manually.',
 'If reading stalls, choose Stop reading. A read also times out after 30 seconds. Retry with a clearer photo or enter the details manually. Closing the camera cancels its pending read.',
 'Review every suggested guest field against the document. Enter phone, email and missing details yourself. A new scan or manual guest edit clears I checked these guest details; confirm the updated details before booking.',
 'Keep Same as guest selected for guest billing. Choose a separate billing recipient only when needed. Reviewing or scanning a document does not book the room, charge a payment or check the guest in.'
 ],notes:['Scanning suggests information; it does not verify identity or document authenticity. Camera quality, glare, focus and document layout affect results.','Photos and raw scanner text are processed on the device. Reviewed fields are saved only through the guest workflow. Scan only documents permitted by your property policy.','These scanner recovery controls are awaiting publication.'],keywords:['scan','camera','passport','ID','stop reading','timeout','review','upload']},
 {id:'walk-in',title:'Book a walk-in guest',area:'Front desk',availability:'Pilot workflow',steps:['On Today, select the room number to start a walk-in.','Enter guest details or scan a document. Review and correct the suggested fields, then confirm that you checked the details.','Keep Same as guest selected unless someone else is paying.','Select stay dates and review the configured room-type price, taxes and fees.','Review the quote and select Book this quoted stay once. Continue through check-in after the reservation saves.'],notes:['A quote does not hold inventory or collect payment. Missing capacity, nightly rates or an active plan must be configured before booking.','Document scanning can miss or misread fields. Staff must review the result.'],keywords:['id','passport','scan','same as guest','bill to','book','rate']},
 {id:'check-in',title:'Check in a reserved guest',area:'Front desk',availability:'Pilot workflow',steps:['Open the confirmed reservation and choose Check in / prepare.','Verify guest and stay details, then choose a room.','After choosing the room, review Payment for room. If it is collapsed, select Review payment. Use Open guest bill to check the charges and recorded balance.','Record money actually received, or verify the existing payment arrangement. Select Continue to check-in to return to the final confirmation. This button does not charge a card.','Confirm that you verified the guest, stay details and payment arrangements. Select Confirm check-in once.','Verify In house before issuing room access under your property procedure.'],notes:['Owners and managers can use Allow dirty room — manager override with a reason. The room stays Dirty and preparation work remains open. Occupancy and maintenance conflicts still apply.','A test payment does not settle a real bill. If the result is uncertain, recover the original request before starting another.'],keywords:['arrival','dirty room','payment','override']},
{id:'sandbox-payment',title:'Prepare or cancel a Stripe test checkout',area:'Guest experience',availability:'Release preview',steps:['As an owner or manager, open Connections and review Stripe payment setup. This read-only status lists missing sandbox configuration without showing secret values. These checks do not verify the Stripe account, webhook delivery or a successful payment.','Use only the designated test property after its Stripe sandbox connection is verified. Open the confirmed reservation and create an active guest arrival link.','Select Prepare Apple Pay / Google Pay test. Verify the prepared amount against the guest bill. The guest must submit arrival details before opening test checkout.','If the bill has changed, review the existing checkout before proceeding. Preparing again does not change an already prepared amount.','To stop an unpaid checkout, an owner or manager selects Cancel / retry test checkout cancellation. Wait for Test checkout cancelled.','If Cancellation pending or an unconfirmed result appears, retry the same cancellation to check and finish it. Do not assume the checkout is stopped.','If payment already completed appears, review it in Stripe. Cancellation is not a refund.','After the signed webhook confirms payment, an owner or manager selects Prepare Apple Pay / Google Pay test again to refresh the result, then selects Record verified test payment to folio. The PMS re-reads the completed Stripe test session and records its session reference once in the authenticated folio ledger. Refresh the folio to verify the receipt.','After confirmed cancellation, an unsubmitted arrival link can be replaced and a new test checkout prepared. Submitted arrival links cannot currently be replaced.'],notes:['This is sandbox testing, not real collection. The signed webhook confirms a test payment but does not change the folio by itself; an owner or manager must use the reconciliation action above. Never use this workflow to represent a real payment.','Wallet buttons depend on the Stripe test account payment-method settings and the guest device and browser. Enable Apple Pay and Google Pay for the test account, then check the hosted Stripe checkout on a compatible device. If a wallet is not offered, use the available card option and have the account owner review Stripe test-mode settings; availability has not yet been verified on iPad, Android, or desktop hardware.','The guest enters payment details only on Stripe-hosted checkout. The PMS never asks staff to copy wallet or card credentials into a PMS field.','Disabling the arrival link alone does not cancel an already opened Stripe checkout. Use the explicit cancellation action.','If your account changed, reopen the reservation under the correct account before continuing.','A timeout does not prove failure. Check the saved result before starting another transaction; do not manually record a payment solely from a timeout message.'],keywords:['stripe','sandbox','test payment','cancel checkout','cancellation pending','wallet','apple pay','google pay']},
 {id:'phone-arrival',title:'Let a guest prepare on their phone',area:'Guest experience',availability:'Pilot workflow',steps:['Open Check in / prepare on the confirmed reservation. Link creation requires a confirmed stay with valid arrival and departure dates, a room type and guest count; correct the reservation first if any are missing.','Under Phone pre-check-in, select Create guest link and Copy link. Send it using your approved communication method. When the guest opens the private link, the portal shows those stay dates, room type and guest count.','The guest may use Scan ID or passport and take a photo or upload one. The browser processes the image and raw scan text on that device. It suggests the legal name and permitted contact-address fields; the guest must review and correct each suggestion before submitting.','The guest submits their reviewed name, optional address, phone, optional email and estimated arrival time. They may separately opt in to stay-related email/text updates and promotional offers; all choices start unchecked.','Use Refresh details to review the submission and the guest’s separately saved stay and promotional email/text choices, including the saved time and notice version. Automated messages are not active. If a guest asks to stop an opted-in channel, select Record guest request next to that choice and confirm. The withdrawal is recorded for this reservation with the staff account and time; it does not create an email or text. Staff must verify the guest against the original ID at arrival, then complete staff-led payment review, room assignment/readiness checks and check-in.'],notes:['Creating a link does not send an email automatically. Links expire after 24 hours. The stay summary is captured when the link is created and omits guest name, room number and price. If the reservation changes before the guest submits arrival details, correct it and replace the unused link. After submission or a test checkout, the link cannot be replaced; staff must review the existing stay.','The ID image and raw scan text stay on the guest device; document numbers and dates of birth are not sent to or stored by the PMS. Only reviewed name/address fields are submitted. Do not treat OCR suggestions as proof of identity or authenticity. Communication choices are stored with a notice version and timestamp. Stay-related email/text and marketing email/text choices are separate and optional. Automated messages and contact-channel verification are not active. Withdrawals are reservation-scoped; do not enable future messaging until property-wide and guest-wide suppression requirements are complete.','Submitted details do not automatically replace saved guest records. Staff still confirm identity, check-in and room access.','Stripe wallet connection and device acceptance remain unfinished; do not promise Apple Pay or Google Pay availability.'],keywords:['online checkin','mobile','phone','guest link','scan ID','passport scan','camera','privacy','apple pay','google pay']},
 {id:'departure',title:'Check out a guest',area:'Front desk',availability:'Pilot workflow',steps:['Open Manage stay.','Review the guest bill and actual payment evidence. Resolve unpaid or unclear amounts through the appropriate billing workflow.','Choose Check out guest under the property procedure.','Review the resulting turnover task in Rooms & housekeeping.'],notes:['Checking out a guest and closing the service day are separate operations.','The live pilot can check out a stay with an unpaid balance. Staff must review payment evidence and follow the property balance procedure before using Check out guest. A checked-out status does not mean the bill is paid.','Release preview: Review checkout shows the remaining guest balance. Select Open folio / review payment to inspect the bill, then reopen Review checkout for a fresh balance review. Staff can confirm only settled balances; owners and managers must document an arrangement for an outstanding balance or credit. Checkout itself does not collect payment or issue a refund. If loading the review times out, check the connection and select Refresh checkout review; a delayed reply will not replace your refreshed review.'],keywords:['checkout','departure','folio','balance']},
 {id:'cleaning-assignments',title:'Plan and save cleaning assignments',area:'Rooms',availability:'Release preview',steps:['Open Rooms & housekeeping, then Turnover tasks. Refresh the queue and expand Plan cleaning assignments.','Select available cleaners and enter each total task limit. Existing queued and in-progress tasks count against the limit. Select Preview assignments.','Review the proposed rooms and staff. Enter Assignment plan reason and select Prepare reviewed batch.','Confirm that you reviewed the proposed rooms, team and task limits, then select Save reviewed assignments.','After confirmation, review the refreshed queue. This does not send staff notifications.','If a result is interrupted, use Check saved assignment batch. Retry exact assignment batch keeps the same request. Do not recreate the plan while its result is unresolved.','Cancel unsaved batch preserves assignments that already saved; otherwise it prevents that request from saving later. Wait for confirmed cancellation before making a new plan.'],notes:['Only unassigned, vacant, unblocked queued work due today or earlier is proposed. Oldest due work is considered first. Task counts are not effort estimates or shift hours.','The server rechecks access, limits, versions and eligibility. A conflict rejects the batch together. Review current work after resolving the saved request.','A not-found receipt may still be in flight. Other turnover edits stay paused until the batch is resolved.','This is manager-reviewed batch assignment, not unattended scheduling. Maximum batch size is 500 tasks.'],keywords:['batch','assign','cleaners','capacity','workload','cancel unsaved','recovery']},
 {id:'housekeeping-productivity',title:'Review completed housekeeping work',area:'Rooms',availability:'Release preview',steps:['As an owner or manager, open Rooms & housekeeping and select Productivity.','Choose From and Through dates covering 1 to 31 days, then select Load housekeeping report.','Review completed turnovers and average cleaning elapsed and inspection wait for each date. On small screens, scroll the table sideways.','Check the report generation time. Load the report again for current results; changing either date clears the previous report.'],notes:['Completion dates use the property current time zone. The report counts completed turnover tasks, not distinct rooms or all assigned work.','Cleaning elapsed is the latest work start to submission; inspection wait is submission to approval. Breaks and delays are included. These are not paid labor hours or employee performance ratings.','Each average shows its sample count. No timing data means no valid duration samples; it is not zero minutes. Cancelled tasks and earlier cleaning attempts are excluded.','This report requires the pending database update. If reporting is unavailable, check owner/manager access and deployment status.'],keywords:['productivity','cleaning time','inspection wait','completed turnovers','housekeeping report']},
 {id:'housekeeping',title:'Find housekeeping and maintenance work',area:'Rooms',availability:'Release preview',steps:['Open Rooms & housekeeping.','Use Room readiness for room cards, Turnover tasks for preparation work, or Maintenance for closures and repairs.','In Room readiness, search by room number or room type and choose a Room filter. Clear filters restores the full list.','As an owner or manager, open Staff workload in Turnover tasks to compare queued, active and inspection work. Refresh turnover queue for updated counts.','Review a room task and choose Assign work to change its assigned person. Check the due date, blockers and staff availability before assigning.','Follow the turnover workflow to complete cleaning and inspection.'],notes:['Workload totals count tasks, not estimated effort or paid hours. Due and blocked counts overlap work-state counts. Inspection work remains attributed to the cleaner. Automatic assignment is not enabled.','Clean and Inspect promotions require the turnover workflow. Mark Dirty for preparation queues or restarts preparation for a vacant room.','Active maintenance uses the property business date and excludes the closure end date. A Clean label alone does not prove a room is bookable.'],keywords:['dirty','clean','inspect','maintenance','turnover','room filter']},
 {id:'lost-found',title:'Register and return a found item',area:'Rooms',availability:'Release preview',steps:['Open Lost and found and choose Add found item.','Enter Item description, Found at, Stored at and Date found. Select Register item once.','Search by description or location and use Held or Returned to narrow the list.','Confirm the claimant and complete the handover under your property procedure.','Select Record return of the item, enter the handover receipt reference, and Confirm item returned.'],notes:['Owners and managers can write; staff can search and read. Do not enter an ID number in the handover reference.','Returned items remain searchable. Return reversal and disposal are not available in this preview.'],keywords:['lost','found','left behind','handover']},
 {id:'storage-move',title:'Move a found item or recover an unfinished move',area:'Rooms',availability:'Release preview',steps:['Select Move on a held item and verify its current physical location.','After moving it, enter New storage location and Reason for move, then Save storage move.','Use View storage history to trace earlier locations, reasons, times and staff references.','If a response is interrupted, use Retry item record. Cancel unsaved move is available for an unfinished move: saved moves are kept; unsaved requests are cancelled.'],notes:['Cancellation does not physically move an item. Reconcile its actual location and refresh before creating a new move.','If another person changed storage first, the old request cannot overwrite that update.'],keywords:['storage','move','retry','cancel','history']},
 {id:'company-billing',title:'Choose the right company billing task',area:'Finance',availability:'Release preview',steps:['Open Company accounts and select the account under Company & group billing.','Use Invoices to review invoices, Payments & refunds to record money already received or returned, Match payments to apply a receipt, and Transfer charges for eligible stay charges.','Review the amount, reference and account before confirming an action.','Use the offered result-check or retry control if a response is interrupted.'],notes:['Payment and refund records do not charge a card or send money through a provider. Matching a receipt does not collect money again.','Needs ledger posting means the receipt has not completed general-ledger posting. Recording, matching and posting are separate tasks.'],keywords:['invoice','refund','company','accounts receivable','payment','ledger']},
{id:'property-comparison',title:'Compare properties and download the report',area:'Management',availability:'Release preview',steps:['Open Property overview. Choose Comparison business date; it starts with the selected property’s current business date. Select Compare properties.','Review Rooms, In house, Arrivals, Departures, Ready vacant, To prepare and Maintenance for each property. The report labels each property’s time zone and selected business date.','Select a property name to switch to that property’s Today dashboard.','Select Download comparison CSV to export the displayed operational counts. If you change the date, select Compare properties again before downloading.'],notes:['Only owner or manager properties in the selected organization are requested. Managers see only properties currently assigned to them.','These are current operational counts for the selected business date, not historical occupancy, revenue, or a forecast. Ready vacant excludes occupied, closed and unfinished-turnover rooms. To prepare includes dirty and inspection rooms and excludes active maintenance.','Unavailable means access changed or the summary could not be verified; it is never a zero. The comparison and CSV contain aggregate counts, not guest, reservation, folio or payment rows. This dashboard remains a release preview until its migration is installed and hosted role checks and hotel acceptance are complete.'],keywords:['multi property','compare','csv','availability','report','ready vacant','to prepare','maintenance']},
{id:'portfolio-rate-inventory',title:'Manage rates and inventory across properties',area:'Management',availability:'Release preview',steps:['As an owner or assigned manager, open Property overview. Select each property you intend to change and choose Load selected property mappings. Review the returned property names, business dates, time zones, currencies, room types and saved rate plans.','Choose First night and End date (exclusive). The starting date must be on or after every selected property’s local business date; the screen defaults to the latest one.','For each property, select Update nightly rate, choose that property’s saved plan, and enter the room price before taxes and fees. The screen displays the selected plan version.','For each property, select Update sellable room capacity, choose that property’s room type and enter the number of rooms to sell each night. Zero closes sales for that room type and date range.','Select Apply selected updates once. Confirm the saved result message. The changes apply to the same explicit date range for each selected property.','If access or a rate-plan version changed, reload property mappings and review the plan before trying again. If the response is interrupted, retry without changing the inputs so the saved request can be checked.'],notes:['This workflow requires owner or manager access for each selected property; a manager cannot change an unassigned property. Room types and plans are selected separately per property; matching names do not mean the IDs are shared.','The database applies all selected nightly-rate and capacity changes in one transaction. A failure at any property rolls back the whole batch. Nightly rates are USD before taxes and fees; no currency conversion is performed.','Capacity cannot exceed configured physical rooms or fall below confirmed reservations and active booking holds. Check the displayed property-local business dates before saving.','This is a release preview until the migration is installed in the hosted PMS, signed-in role behavior and hotel data are verified, and property owners accept the workflow.'],keywords:['central rates','portfolio rates','multi property rates','capacity','inventory','rate plan','room type']},
{id:'support-tickets',title:'Send and follow a support request',area:'Support',availability:'Release preview',steps:['Open Help & manual and find Contact iRatePilot support.','Choose a topic, enter a short subject and explain the issue without guest names, ID numbers, payment-card data, passwords, or other sensitive details.','Select Send support request once. If the result is uncertain, retry the unchanged request; its saved request identity prevents a duplicate ticket.','Find the ticket under Your property requests. Refresh to check its current status and read any iRatePilot support reply.'],notes:['Property staff can see their own requests; owners and managers can review requests for the property. Only the designated platform administrator can open ticket details and reply in /platform-admin. Use Review support-access audit there to inspect recorded ticket access.','This feature is a release preview until the support-ticket migration is installed and the platform administrator account is verified. It is not a 24/7 support commitment or a diagnostic-log upload.'],keywords:['support ticket','support request','contact support','help','reply','support access audit']},
{id:'booking-source-report',title:'Review booking sources and arrival outcomes',area:'Reports',availability:'Release preview',steps:['Select the correct property, open Reports, and keep Report group on Operations & bookings.','In Report, select Booking sources & arrival outcomes. Set From and Until (exclusive) to the arrival dates you want, then select Load reports.','Review scheduled arrivals, cancellations and no-shows, then compare the known full-stay booked values for active and cancelled arrivals by saved source. Check the separate unknown-amount counts before interpreting totals. Select Export CSV or Print / save PDF to keep the loaded report.'],notes:['The cohort contains all current reservation records scheduled to arrive in the selected dates. Counts use each reservation’s current saved status; this is not a cancellation-event-date report.','No-show arrivals are included in cancelled arrivals. Do not add the two counts or rates together. A missing source is grouped as Other / unknown.','Booked values are full-stay guest totals, not earned revenue, payments collected, processor settlement, channel commission or profit; known subtotals can be incomplete when amount counts are nonzero. A saved source does not prove a connected OTA. Verify provider status separately under Connections.','This report is a release preview until its connected report service, hosted role checks and live hotel data are verified.'],keywords:['booking source','channel source','arrival outcomes','cancellation share','no-show share','direct','iRatePilot OTA','Booking.com']}
,{id:'channel-performance-report',title:'Compare channel booking performance',area:'Reports',availability:'Release preview',steps:['Select the correct property, open Reports, and keep Report group on Operations & bookings.','In Report, select Channel performance. Set From and Until (exclusive) to the scheduled arrival dates you want, then select Load reports.','Compare active stays, cancellations and no-shows by saved source. Review active accommodation booked value, recorded OTA fees, estimated contribution and unknown counts.','If amounts or fees are unavailable, check the reservation’s saved accommodation amount and OTA fee before interpreting the row. Export CSV or print the loaded report if needed.'],notes:['Accommodation booked value and recorded OTA fees cover active stays only; taxes and property fees are excluded from accommodation. Cancellations and no-shows are shown for the full cohort. Cancellation and no-show rates use the full arrival cohort.','Estimated contribution subtracts recorded OTA fees from accommodation booked value. It is not earned revenue, collected payment, settlement, accounting profit or final channel profitability. It excludes processor costs, missing commissions/refunds and operating expenses. Direct bookings assume no OTA fee.','Imported and unrecognized source labels remain separate; source values do not prove a live OTA connection. Check Connections for channel status.','This report is a release preview until hosted role checks, fee completeness, source accuracy and hotel acceptance are verified.'],keywords:['channel performance','ota fees','channel profitability','contribution','accommodation value','cancellation rate','no show rate','csv']}
,{id:'feature-availability',title:'Check feature availability before using a workflow',area:'Getting started',availability:'Pilot workflow',steps:['Open Feature availability from the PMS footer and review the audit date and full-scope requirement counts. The page is a release summary, not a live service-health check.','Read the status and evidence notes for the specific area you need. Pilot workflow describes a tested path in the connected pilot; Release preview or Development preview can describe work that is not active for your property.','Before relying on a payment, OTA, email, mobile or other provider connection, verify its connection status in the relevant PMS screen and complete the provider-approved test for the selected property.','For an unfamiliar or blocked task, search Help & manual by the task name. Follow only instructions marked for an available workflow, refresh the property workspace, and confirm the saved result on screen.','If a feature is unavailable or the result is uncertain, stop before retrying a payment, changing an OTA reservation or editing guest data. Keep the request reference and ask your property owner or iRatePilot administrator to reconcile the saved state.'],notes:['Partial evidence can include local tests, isolated database rehearsals or an unverified hosted screen. It does not prove production readiness. An unverified item has not passed its required acceptance checks.','A saved connection or enabled toggle does not prove provider approval, end-to-end delivery, settlement, property certification or support coverage. Complete a controlled round trip before accepting real bookings through a channel.','Use the current property and business date shown in the PMS. Portfolio summaries and downloaded reports are snapshots; refresh before acting after another staff member changes the workspace.','Do not treat a preview, sample property, test payment or sample room map as a production hotel acceptance result.'],keywords:['feature availability','release status','launch readiness','pilot workflow','release preview','development preview','evidence','connected provider']}
,{"id":"digital-room-keys","title":"Check digital room-key availability","area":"Guest experience","availability":"Release preview","steps":["The PMS does not currently issue or revoke digital room keys. Do not look for a key button in the reservation or check-in screen.","Continue using the property's approved lock-vendor system and follow its current identity, access, and key-expiration procedures.","If a guest needs a replacement key or a room move, update the lock-vendor system and the PMS room assignment through their separate approved workflows.","Before enabling a future connection, the owner or manager must complete vendor approval, property and room mapping, test issuance and revocation, guest-device delivery, and checkout-expiration checks."],"notes":["The PMS currently contains only a provider-neutral integration contract. It is not connected to a lock vendor and must not be treated as a functioning key system.","Never paste a door code, API secret, guest identity document, or access token into PMS notes, support tickets, or AI questions."],"keywords":["digital room key","door lock","electronic key","mobile key","lock integration"]},
];
/** The guide's screen filter indexes documented workflows; it does not claim that each one is enabled. */
